  test('same-second-completion negative: the COARSE daemon\u2192transport witness route stays REFUSAL-ONLY — every coarse admitted witness outcome on the bound-window route refuses with its own label, and only the exact tuple may credit (route (c), §32)', async () => {
    // The codex-round-16 finding-2 adjudication (option b: the route is
    // explicitly classified UNSATISFIABLE, not qualified) applies to the
    // COARSE tuple: the route is entered only when markerTime <
    // daemonStart + 1000, while its coarse establishment requires
    // markerTime >= childOsStartInstantMs + 1000 under childOsStartInstantMs
    // >= daemonStart — jointly markerTime >= daemonStart + 1000,
    // contradicting the entry condition. No bound may be weakened (the
    // \u00a726.7 freeze), so the COARSE route is REFUSAL-ONLY: every coarse
    // witness quality refuses with its own named label (the
    // \u00a728.9-\u00a728.12 refusal evidence kept intact \u2014 never folded), and no
    // coarse verdict can carry a witnessClass. The EXACT-MODE supersession
    // (route (c), \u00a732) is the bounded repair \u00a728.22 itself proposed: with
    // the closed exact tuple the marker window collapses and the exact
    // witness establishes — asserted by its own dedicated test. This test
    // pins the coarse half byte-identically.
    const endpoint = (pid, ppid, startIdentity, startInstantEpochMs, read, readStarted) => ({
      localProcessObservationVersion: 3, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid, ppid, startIdentity, nonce: NONCE, startInstantEpochMs, ppidChangedFromCapture: null },
      queried: { pid, nonce: NONCE },
      readStartedEpochMs: readStarted ?? read - 50, identityReadEpochMs: read, readEpochMs: read, absenceConfirmed: null,
    });
    const brokerWitness = (childOsStartInstantMs, boundaryEpochMs, recordVersion = 2) => ({
      localProcessObservationVersion: 3, class: 'spawn-ancestry-witness', status: 'established', reason: null,
      identity: recordVersion === 2
        ? { version: 3, startIdentityExact: false, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE, writerPid: daemon.pid, writerStartIdentity: daemon.startIdentity, childPid: 5300, childPpid: daemon.pid, childStartIdentity: 'S-TRANSPORT', childNonce: NONCE, boundaryEpochMs, firstWriteEpochMs: boundaryEpochMs + 10, startOriginMs: null, firstWritePreciseMs: null, childOsStartInstantMs }
        : { version: 1, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE, writerPid: daemon.pid, writerStartIdentity: daemon.startIdentity, childPid: 5300, childPpid: daemon.pid, childStartIdentity: 'S-TRANSPORT', childNonce: NONCE, boundaryEpochMs, firstWriteEpochMs: boundaryEpochMs + 10, startOriginMs: null, firstWritePreciseMs: null },
      readStartedEpochMs: boundaryEpochMs, readEpochMs: boundaryEpochMs + 10,
    });
    // The daemon's floor is 1800; every schedule below keeps the marker
    // INSIDE the bound window (marker < daemonStart + 1000 = 2800) so the
    // witness route is consulted, and the writer bounds hold (the daemon's
    // own witness write 2510 postdates its floor + 1000, its collection
    // bound 2520 postdates the write \u2014 the round-7/12 parent bindings).
    const run = (markerEpochMs, witness) => joinAncestryHops({
      nonce: NONCE,
      companionObservation: null,
      daemonObservation: endpoint(daemon.pid, daemon.ppid, daemon.startIdentity, 1800, 2700, 2520),
      transportMarker: { pid: 5300, ppid: daemon.pid, nonce: NONCE },
      expectedTransportNonce: NONCE,
      markerEpochMs,
      daemonSpawnWitness: witness,
    });
    // (a) marker inside the witnessed child's first second \u2192 ambiguous.
    const ambiguous = run(2500, brokerWitness(1800, 2500));
    assert.deepEqual([ambiguous.hops[1].status, ambiguous.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'], JSON.stringify(ambiguous.hops[1]));
    // (b) marker BELOW the witnessed child's floor \u2192 demonstrably unbound.
    const unbound = run(1900, brokerWitness(2000, 2500));
    assert.deepEqual([unbound.hops[1].status, unbound.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-unbound'], JSON.stringify(unbound.hops[1]));
    // (c) a v1 replay record (no numeric instant) \u2192 unbound.
    const v1 = run(2500, brokerWitness(undefined, 2500, 1));
    assert.deepEqual([v1.hops[1].status, v1.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-unbound'], JSON.stringify(v1.hops[1]));
    for (const verdict of [ambiguous, unbound, v1]) {
      assert.equal(verdict.hops[1].witnessClass, undefined,
        'no COARSE witness outcome on the bound-window route ever carries a witnessClass');
      assert.equal(verdict.companionToTransportAttributed, false);
    }
    // The SOURCE-LEVEL classification: the exact guard gates the only
    // crediting arm; the coarse fallback is the named unsatisfiable label
    // (fail-closed \u2014 the coarse route never composes an established verdict).
    const { readFileSync } = await import('node:fs');
    const observerModulePath = fileURLToPath(new URL('../tools/shell-wait-probe/local-process-observation.mjs', import.meta.url));
    const source = readFileSync(observerModulePath, 'utf8');
    const daemonHopStart = source.indexOf('EXPLICIT UNSATISFIABILITY');
    assert.ok(daemonHopStart > 0, 'the daemon witness establishment arm carries the named unsatisfiable classification');
    const armSlice = source.slice(daemonHopStart, source.indexOf('} else if (witnessOutcome !== null) {', daemonHopStart));
    assert.ok(armSlice.includes('witnessOutcome.exact === true'), 'the crediting arm is gated on the exact tuple');
    assert.ok(armSlice.includes("hopVerdict('unestablished', 'spawn-witness-route-unsatisfiable', null)"),
      'the coarse fallback stays fail-closed with the named unsatisfiable label');
    assert.ok(armSlice.includes("witnessClass: /** @type {const} */ ('spawn-boundary-capture')"),
      'the exact guard is the only crediting arm (the registered route-(c) repair)');
  });

  test('same-second-completion route (c): the EXACT daemon\u2192transport witness establishes the same-second hop — ties are SAME generation, strict inequality is DIFFERENT, and mixed exactness keeps the coarse refusals (\u00a732)', () => {
    // The \u00a728.22 bounded repair, implemented: with the closed exact tuple
    // (v3 record + exact daemon endpoint) the marker binding collapses to
    // `markerTime >= childExactStart` — no +1000 window — so the
    // same-second daemon\u2192transport hop establishes WITH its named
    // witnessClass. The coarse control and the mixed-exactness control on
    // the SAME schedule keep the coarse refusal labels byte-identically
    // (the \u00a732 two-mode discipline).
    const DAEMON_EXACT = 'kinfo:1793849000:500000'; // 1793849000500
    const TRANSPORT_EXACT = 'kinfo:1793849000:700000'; // 1793849000700
    const exactEndpoint = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: daemon.pid, ppid: daemon.ppid, startIdentity: DAEMON_EXACT, nonce: NONCE, startInstantEpochMs: 1793849000500, ppidChangedFromCapture: null },
      queried: { pid: daemon.pid, nonce: NONCE },
      readStartedEpochMs: 1793849001500, identityReadEpochMs: 1793849002000, readEpochMs: 1793849002000, absenceConfirmed: null,
    };
    const exactWitness = (over = {}) => ({
      localProcessObservationVersion: 4, class: 'spawn-ancestry-witness', status: 'established', reason: null,
      identity: {
        version: 3, startIdentityExact: true, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE,
        writerPid: daemon.pid, writerStartIdentity: DAEMON_EXACT,
        childPid: 5300, childPpid: daemon.pid, childStartIdentity: TRANSPORT_EXACT, childNonce: NONCE,
        boundaryEpochMs: 1793849000800, firstWriteEpochMs: 1793849000900,
        startOriginMs: null, firstWritePreciseMs: null, childOsStartInstantMs: 1793849000700,
        ...over,
      },
      readStartedEpochMs: 1793849000800, readEpochMs: 1793849000900,
    });
    // (§32.10 Finding 1) the marker carries its writer's CAPTURED start
    // identity (schema-additive, like the runtime's persisted marker): the
    // exact tuple binds it to the record's childStartIdentity. The default
    // is the MATCHING captured identity (the honest-chain shape); the
    // successor/missing-identity negatives below vary it.
    const run = (daemonObservation, witness, markerEpochMs, markerStartIdentity = TRANSPORT_EXACT) => joinAncestryHops({
      nonce: NONCE,
      companionObservation: null,
      daemonObservation,
      transportMarker: { pid: 5300, ppid: daemon.pid, nonce: NONCE, ...(markerStartIdentity === null ? {} : { startIdentity: markerStartIdentity }) },
      expectedTransportNonce: NONCE,
      markerEpochMs,
      daemonSpawnWitness: witness,
    });
    // The strict-order schedule: daemon 500, transport 700, boundary 800,
    // write 900, marker 1400 — all inside the daemon's creation second
    // (daemonStart + 1000 = 1793849001500 > marker), so the arithmetic path
    // alone refuses; the exact witness establishes.
    const exact = run(exactEndpoint, exactWitness(), 1793849001400);
    assert.deepEqual([exact.hops[1].status, exact.hops[1].reason], ['established', null], JSON.stringify(exact.hops[1]));
    assert.equal(exact.hops[1].witnessClass, 'spawn-boundary-capture', 'the exact witness carries its named witnessClass');
    // TIES = SAME GENERATION at the true window edge: marker == the
    // persisted HALF-EXACT child start (child `kinfo:1793849000:700500` —
    // creation 1793849000700.5 = the persisted 1793849000701's INCLUDED
    // window left edge), boundary == childExactStart, firstWrite ==
    // writerExactStart — every ordering tie still establishes (the §32 tie
    // convention). (codex gate round 63 review-mwfxlzpe-0fve20, Finding 1)
    // the ALIGNED child's tie is NO LONGER an establishing tie: its
    // persisted instant equals the creation, so the marker's rounded window
    // [R - 0.5, R + 0.5) contains writes before the child existed — the
    // named ambiguity asserted below.
    const halfExactChild = 'kinfo:1793849000:700500';
    const tied = run(exactEndpoint, exactWitness({
      childStartIdentity: halfExactChild,
      childOsStartInstantMs: 1793849000701,
      boundaryEpochMs: 1793849000701,
      firstWriteEpochMs: 1793849000701,
    }), 1793849000701, halfExactChild);
    assert.deepEqual([tied.hops[1].status, tied.hops[1].reason], ['established', null], JSON.stringify(tied.hops[1]));
    assert.equal(tied.hops[1].witnessClass, 'spawn-boundary-capture');
    const alignedTie = run(exactEndpoint, exactWitness({ boundaryEpochMs: 1793849000700, firstWriteEpochMs: 1793849000700 }), 1793849000700);
    assert.deepEqual([alignedTie.hops[1].status, alignedTie.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'], JSON.stringify(alignedTie.hops[1]));
    assert.equal(alignedTie.hops[1].witnessClass, undefined);
    // STRICT INEQUALITY = DIFFERENT GENERATION: a marker strictly before the
    // exact child creation refuses `spawn-witness-marker-generation-unbound`.
    const before = run(exactEndpoint, exactWitness(), 1793849000600);
    assert.deepEqual([before.hops[1].status, before.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-unbound'], JSON.stringify(before.hops[1]));
    // MIXED EXACTNESS: the SAME identities with the exactness NOT declared
    // (v3 flag false) fall back to the coarse windows — the marker inside
    // the child's first second is ambiguous, never credited.
    const mixed = run(exactEndpoint, exactWitness({ startIdentityExact: false }), 1793849001400);
    assert.deepEqual([mixed.hops[1].status, mixed.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'], JSON.stringify(mixed.hops[1]));
    assert.equal(mixed.hops[1].witnessClass, undefined);
    // An exact record against a COARSE endpoint is a different generation
    // identity (writer-foreign), never silently demoted to exactness.
    const coarseEndpoint = {
      ...exactEndpoint,
      localProcessObservationVersion: 3,
      observation: { ...exactEndpoint.observation, startIdentity: 'S-DAEMON', startInstantEpochMs: 1793849000500 },
    };
    const foreign = run(coarseEndpoint, exactWitness(), 1793849001400);
    assert.deepEqual([foreign.hops[1].status, foreign.hops[1].reason], ['unestablished', 'spawn-witness-writer-foreign'], JSON.stringify(foreign.hops[1]));
    // The COARSE control on the same schedule: a coarse record + coarse
    // endpoint keeps the registered coarse refusal label.
    const coarseRecord = exactWitness({
      startIdentityExact: false,
      writerStartIdentity: 'S-DAEMON',
      childStartIdentity: 'S-TRANSPORT',
    });
    const coarse = run(coarseEndpoint, coarseRecord, 1793849001400);
    assert.deepEqual([coarse.hops[1].status, coarse.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'], JSON.stringify(coarse.hops[1]));
    assert.equal(coarse.hops[1].witnessClass, undefined);
    // (§32.10 Finding 2) NO ±1000 BAND IN EXACT MODE: the round-4 proximity
    // conjunct (boundary − marker > 1000 → unbound) is a COARSE conjunct.
    // In exact mode the marker's generation is bound by the captured
    // identity + the exact ordering, so a capture window MORE than a second
    // after the marker still establishes (the emitter's bounded ingress poll
    // may legitimately complete late).
    const lateCapture = run(
      {
        ...exactEndpoint,
        readStartedEpochMs: 1793849012500,
        identityReadEpochMs: 1793849013000,
        readEpochMs: 1793849013000,
      },
      exactWitness({ boundaryEpochMs: 1793849011000, firstWriteEpochMs: 1793849012000 }),
      1793849001400,
    );
    assert.deepEqual([lateCapture.hops[1].status, lateCapture.hops[1].reason], ['established', null], JSON.stringify(lateCapture.hops[1]));
    assert.equal(lateCapture.hops[1].witnessClass, 'spawn-boundary-capture',
      'boundary − marker > 1000 never refuses an otherwise-sound exact tuple (no ±1000 band)');
    // The COARSE control for the same late-capture schedule: the proximity
    // conjunct applies and refuses unbound — the windows are coarse-only.
    const lateCaptureCoarse = run(
      {
        ...coarseEndpoint,
        readStartedEpochMs: 1793849012500,
        identityReadEpochMs: 1793849013000,
        readEpochMs: 1793849013000,
      },
      exactWitness({
        startIdentityExact: false,
        writerStartIdentity: 'S-DAEMON',
        childStartIdentity: 'S-TRANSPORT',
        boundaryEpochMs: 1793849011000,
        firstWriteEpochMs: 1793849012000,
      }),
      1793849001400,
    );
    assert.deepEqual([lateCaptureCoarse.hops[1].status, lateCaptureCoarse.hops[1].reason], ['unestablished', 'spawn-witness-marker-generation-unbound'], JSON.stringify(lateCaptureCoarse.hops[1]));
  });

  test('same-second-completion route (c) negative: a same-pid SUCCESSOR\u2019s marker (its own captured start identity) never rides the witnessed child\u2019s exact generation — the captured-identity binding refuses child-foreign (\u00a732.10 Finding 1)', () => {
    // The reviewer\u2019s exact schedule: the witnessed child is
    // kinfo:1000:400000 (1000400 ms); a same-pid successor later writes a
    // fresh marker whose CAPTURED start identity is kinfo:1000:700000
    // (1000700 ms) and whose mtime is 1000750. Before the captured-identity
    // binding this hop established with witnessClass — the successor\u2019s
    // marker credited as the witnessed child\u2019s. Exact mode binds the
    // marker\u2019s captured identity to the record\u2019s childStartIdentity
    // via the child-foreign conjunct: a different exact identity is a
    // DIFFERENT generation and refuses.
    const DAEMON = 'kinfo:1000:0'; // 1000000
    const CHILD = 'kinfo:1000:400000'; // 1000400
    const SUCCESSOR = 'kinfo:1000:700000'; // 1000700
    const daemonEndpoint = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: daemon.pid, ppid: daemon.ppid, startIdentity: DAEMON, nonce: NONCE, startInstantEpochMs: 1000000, ppidChangedFromCapture: null },
      queried: { pid: daemon.pid, nonce: NONCE },
      readStartedEpochMs: 1000950, identityReadEpochMs: 1002000, readEpochMs: 1002000, absenceConfirmed: null,
    };
    const witness = {
      localProcessObservationVersion: 4, class: 'spawn-ancestry-witness', status: 'established', reason: null,
      identity: {
        version: 3, startIdentityExact: true, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE,
        writerPid: daemon.pid, writerStartIdentity: DAEMON,
        childPid: 5300, childPpid: daemon.pid, childStartIdentity: CHILD, childNonce: NONCE,
        boundaryEpochMs: 1000800, firstWriteEpochMs: 1000900,
        startOriginMs: null, firstWritePreciseMs: null, childOsStartInstantMs: 1000400,
      },
      readStartedEpochMs: 1000800, readEpochMs: 1000900,
    };
    const verdict = joinAncestryHops({
      nonce: NONCE,
      companionObservation: null,
      daemonObservation: daemonEndpoint,
      transportMarker: { pid: 5300, ppid: daemon.pid, nonce: NONCE, startIdentity: SUCCESSOR },
      expectedTransportNonce: NONCE,
      markerEpochMs: 1000750,
      daemonSpawnWitness: witness,
    });
    assert.deepEqual([verdict.hops[1].status, verdict.hops[1].reason], ['unestablished', 'spawn-witness-child-foreign'], JSON.stringify(verdict.hops[1]));
    assert.equal(verdict.hops[1].witnessClass, undefined, 'a successor\u2019 marker never carries the witnessed child\u2019 witnessClass');
    assert.equal(verdict.companionToTransportAttributed, false);
  });

