    // them.
    const { observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const PREDECESSOR = 'kinfo:5:0'; // the OLD generation the kinfo query observes
    const NEWER = 'kinfo:9:0'; // the adjudication's newer bound generation
    const PS_TEXT = 'Thu Jan  1 00:00:05 1970'; // second 5: the predecessor's own coarse representation
