          if (args.includes('eww')) return { code: 0, stdout: `node 4194303 ZCODE_SHELL_WAIT_CAPTURE_NONCE=${nonce}\n`, stderr: '' };
          psCalls += 1;
          if (psCalls >= 2) return { code: 0, stdout: '', stderr: '' }; // the EMPTY ps result: absence WAS observed
          return { code: 0, stdout: ` 4194303  4194302 ${PS_TEXT}\n`, stderr: '' };
