  test('route (c) first-exact downgrade carry (codex gate round 13, Finding 2): the FIRST read\u2019s exact successor is preserved read-order-agnostically — a later absence latches the reuse', async () => {
    // The codex-review finding: when the first read observes an exact
    // successor but the second read degrades to matching ps text, the
    // downgrade dropped the first read's exact evidence (the round-12 rule
    // was second-read-specific). The preservation is now
    // READ-ORDER-AGNOSTIC: whichever read supplied the exact identity, that
    // observation + bounds ride the observation verdict for replacement
    // detection.
    const { observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const ORIGINAL = 'kinfo:1:100000';
    const SUCCESSOR = 'kinfo:1:500000'; // the FIRST read observes the exact same-second successor
    const PS_TEXT = 'Thu Jan  1 00:00:01 1970'; // second 1: the coarse representation both reads verify
    const nonce = 'a'.repeat(64);
    let kinfoCalls = 0;
    const verdict = await observeLocalProcess({
      pid: 4_194_303, nonce, expectedStartIdentity: ORIGINAL,
      absenceConfirmation: async () => 'absent',
      osSeams: {
        platform: 'darwin',
        runProcess: async (launch) => {
          const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
          if (args.includes('eww')) return { code: 0, stdout: `node 4194303 ZCODE_SHELL_WAIT_CAPTURE_NONCE=${nonce}\n`, stderr: '' };
          return { code: 0, stdout: ` 4194303  4194302 ${PS_TEXT}\n`, stderr: '' };
        },
        kinfoExact: async () => {
          kinfoCalls += 1;
          if (kinfoCalls === 1) return { sec: 1, usec: 500000 }; // the FIRST read observes the exact successor
          throw new Error('the exact bridge failed transiently'); // the SECOND read degrades
        },
      },
    });
    // (codex gate round 31, Finding 1) the mixed-read carry guard now
    // REFUSES this schedule at the observation layer — the explicit successor
    // carry is never accepted as established (the runtime ancestry/duty hops
    // must not bind across generations on the matching coarse text alone) —
    // and the refusal RIDES the carried evidence + bounds, so the exit
    // adjudication below consumes the same carried rules and still latches
    // the reuse.
    assert.deepEqual([verdict.status, verdict.reason], ['unestablished', 'start-identity-generation-changed'],
      `the explicit successor carry refuses at the observation layer and rides the refusal (measured: ${JSON.stringify(verdict)})`);
    // The FIRST read's exact successor identity is separately preserved.
    assert.equal(verdict.observedStartIdentity, SUCCESSOR, 'the first read\u2019s exact successor identity is preserved');
    assert.ok(Number.isSafeInteger(verdict.observedIdentityReadEpochMs) && Number.isSafeInteger(verdict.observedIdentityCompletedEpochMs),
      `the exact observation's bounds ride the verdict (measured: ${verdict.observedIdentityReadEpochMs} / ${verdict.observedIdentityCompletedEpochMs})`);
    // The adjudication: the later confirmed absence triggers the replacement
    // detection.
    const presence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 4_194_303, ppid: 4_194_302, startIdentity: ORIGINAL, nonce, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
      queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: verdict.readEpochMs - 1000, identityReadEpochMs: verdict.readEpochMs - 900, readEpochMs: verdict.readEpochMs - 800, absenceConfirmed: null,
    };
    const absence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: verdict.readEpochMs + 400, identityReadEpochMs: verdict.readEpochMs + 450, readEpochMs: verdict.readEpochMs + 500, absenceConfirmed: true,
    };
    const exit = await adjudicateLocalExit({ presence, absenceReads: [verdict, absence] });
    assert.deepEqual([exit.status, exit.reason], ['unestablished', 'pid-start-identity-reused'],
      `the carried exact evidence detects the reuse (measured: ${JSON.stringify({ status: exit.status, reason: exit.reason })})`);
  });

