  test('route (c) first-read failure kernel bounds (codex gate round 13, Finding 5): a NONCE-MISMATCH carry dates the kinfo-observed predecessor with the KERNEL bounds — the stale predecessor is discarded', async () => {
    // The codex-review finding: the tighter kinfo bounds were honored only
    // through the ordinary-error ride helper — the nonce-mismatch,
    // marker-gone and missing-second-read branches still constructed their
    // carries with beforeTakenEpochMs/beforeResolvedEpochMs (the ENTIRE
    // combined read's window). kinfo collected during [20000,20100], ps
    // completing at 23000, and a newer presence at [22000,22100] produced
    // pid-start-identity-ambiguous; the kernel bounds route all first-read
    // failure carries through the same resolution, so the stale predecessor
    // is discarded and the lawful outcome holds.
    const { observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const PREDECESSOR = 'kinfo:5:0';
    const NEWER = 'kinfo:9:0';
    const PS_TEXT = 'Thu Jan  1 00:00:05 1970';
    const nonce = 'a'.repeat(64);
    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    let psCalls = 0;
    const verdict = await observeLocalProcess({
      pid: 4_194_303, nonce, expectedStartIdentity: PREDECESSOR,
      absenceConfirmation: async () => 'absent',
      osSeams: {
        platform: 'darwin',
        runProcess: async (launch) => {
          const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
          if (args.includes('eww')) {
            await sleep(2800); // the marker read completes ~2800 ms after the kinfo query — and MISMATCHES
            return { code: 0, stdout: `node 4194303 ZCODE_SHELL_WAIT_CAPTURE_NONCE=${'b'.repeat(64)}\n`, stderr: '' }; // a FOREIGN nonce: mismatch
          }
          psCalls += 1;
          if (psCalls === 1) await sleep(2800); // the read's own ps query: completes ~2800 ms after the kinfo query
          return { code: 0, stdout: ` 4194303  4194302 ${PS_TEXT}\n`, stderr: '' };
        },
        kinfoExact: async () => {
          await sleep(100); // the kinfo query's own window: ~100 ms
          return { sec: 5, usec: 0 };
        },
      },
    });
    // The nonce-mismatch carry rides the observed predecessor.
    assert.deepEqual([verdict.status, verdict.reason], ['unestablished', 'liveness-read-failed'], JSON.stringify(verdict));
    assert.equal(verdict.observedStartIdentity, PREDECESSOR, 'the kinfo-observed predecessor rides the nonce-mismatch carry');
    // The carried window is the KERNEL window (~100 ms — never the ~2900 ms
    // combined read).
    assert.ok(Number.isSafeInteger(verdict.observedIdentityReadEpochMs) && Number.isSafeInteger(verdict.observedIdentityCompletedEpochMs),
      `both bounds ride the carry (measured: ${verdict.observedIdentityReadEpochMs} / ${verdict.observedIdentityCompletedEpochMs})`);
    assert.ok(verdict.observedIdentityCompletedEpochMs - verdict.observedIdentityReadEpochMs <= 250,
      `the carried window is the KERNEL window (measured width: ${verdict.observedIdentityCompletedEpochMs - verdict.observedIdentityReadEpochMs})`);
    // The adjudication: the NEWER presence baseline sits strictly AFTER the
    // carried kernel window — the stale predecessor is discarded.
    const baselineRead = verdict.readEpochMs - 50;
    const presence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 4_194_303, ppid: 4_194_302, startIdentity: NEWER, nonce, startInstantEpochMs: 9000, ppidChangedFromCapture: null },
      queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: baselineRead - 1000, identityReadEpochMs: baselineRead, readEpochMs: baselineRead + 10, absenceConfirmed: null,
    };
    const absence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: baselineRead + 900, identityReadEpochMs: baselineRead + 950, readEpochMs: baselineRead + 1000, absenceConfirmed: true,
    };
    const exit = await adjudicateLocalExit({ presence, absenceReads: [verdict, absence] });
    assert.equal(exit.status, 'disappeared',
      `the stale predecessor is discarded — the lawful disappearance holds (measured: ${JSON.stringify({ status: exit.status, reason: exit.reason })})`);
    assert.notEqual(exit.reason, 'pid-start-identity-ambiguous', 'the loose-window misdating never returns');
  });

  test('route (c) first-read failure kernel bounds controls (codex gate round 13, Finding 5): the ordinary-error ride is unchanged and a kinfo window genuinely overlapping the presence still classifies AMBIGUOUS', async () => {
    // The controls: (a) the ORDINARY-error branch (the round-12 ride helper)
    // is unchanged — the same schedule with a THROWING environment query
    // keeps the kernel-bounds ride and the lawful disappearance; (b) a kinfo
    // window genuinely spanning the newer presence classifies the carried
    // predecessor as the AMBIGUOUS fact.
    const { observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const PREDECESSOR = 'kinfo:5:0';
    const NEWER = 'kinfo:9:0';
    const PS_TEXT = 'Thu Jan  1 00:00:05 1970';
    const nonce = 'a'.repeat(64);
    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const runSchedule = async (kinfoSleepMs, markerFailure) => {
      let psCalls = 0;
      return observeLocalProcess({
        pid: 4_194_303, nonce, expectedStartIdentity: PREDECESSOR,
        absenceConfirmation: async () => 'absent',
        osSeams: {
          platform: 'darwin',
          runProcess: async (launch) => {
            const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
            if (args.includes('eww')) {
              await sleep(2800);
              if (markerFailure === 'throw') throw new Error('the environment query failed transiently');
              return { code: 0, stdout: `node 4194303 ZCODE_SHELL_WAIT_CAPTURE_NONCE=${'b'.repeat(64)}\n`, stderr: '' };
            }
            psCalls += 1;
            if (psCalls === 1) await sleep(2800);
            return { code: 0, stdout: ` 4194303  4194302 ${PS_TEXT}\n`, stderr: '' };
          },
          kinfoExact: async () => {
            await sleep(kinfoSleepMs);
            return { sec: 5, usec: 0 };
          },
        },
      });
    };
    // Control (a): the ORDINARY-error branch — the round-12 ride helper
    // already dated the carry with the kernel bounds; the lawful
    // disappearance holds (unchanged).
    const ordinary = await runSchedule(100, 'throw');
    assert.deepEqual([ordinary.status, ordinary.reason], ['unestablished', 'liveness-read-failed'], JSON.stringify(ordinary));
    assert.equal(ordinary.observedStartIdentity, PREDECESSOR, 'the predecessor rides the ordinary-error branch');
    assert.ok(ordinary.observedIdentityCompletedEpochMs - ordinary.observedIdentityReadEpochMs <= 250,
      `the ordinary-error branch keeps the kernel window (measured width: ${ordinary.observedIdentityCompletedEpochMs - ordinary.observedIdentityReadEpochMs})`);
    const ordinaryBaseline = ordinary.readEpochMs - 50;
    const ordinaryPresence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 4_194_303, ppid: 4_194_302, startIdentity: NEWER, nonce, startInstantEpochMs: 9000, ppidChangedFromCapture: null },
      queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: ordinaryBaseline - 1000, identityReadEpochMs: ordinaryBaseline, readEpochMs: ordinaryBaseline + 10, absenceConfirmed: null,
    };
    const ordinaryAbsence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: ordinaryBaseline + 900, identityReadEpochMs: ordinaryBaseline + 950, readEpochMs: ordinaryBaseline + 1000, absenceConfirmed: true,
    };
    const ordinaryExit = await adjudicateLocalExit({ presence: ordinaryPresence, absenceReads: [ordinary, ordinaryAbsence] });
    assert.equal(ordinaryExit.status, 'disappeared',
      `the ordinary-error branch keeps the lawful disappearance (measured: ${JSON.stringify({ status: ordinaryExit.status, reason: ordinaryExit.reason })})`);
    // Control (b): a kinfo window GENUINELY SPANNING the newer presence —
    // the carried predecessor classifies AMBIGUOUS (never stale, never
    // latched).
    const overlapping = await runSchedule(2900, 'mismatch');
    const overlapBaseline = overlapping.observedIdentityReadEpochMs + 1500; // strictly inside the kinfo window
    const overlapPresence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 4_194_303, ppid: 4_194_302, startIdentity: NEWER, nonce, startInstantEpochMs: 9000, ppidChangedFromCapture: null },
      queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: overlapBaseline - 10, identityReadEpochMs: overlapBaseline, readEpochMs: overlapBaseline + 10, absenceConfirmed: null,
    };
    const overlapAbsence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: overlapBaseline + 20, identityReadEpochMs: overlapBaseline + 25, readEpochMs: overlapBaseline + 30, absenceConfirmed: true,
    };
    const overlapExit = await adjudicateLocalExit({ presence: overlapPresence, absenceReads: [overlapping, overlapAbsence] });
    assert.deepEqual([overlapExit.status, overlapExit.reason], ['unestablished', 'pid-start-identity-ambiguous'],
      `a genuinely overlapping kinfo window still classifies AMBIGUOUS (measured: ${JSON.stringify({ status: overlapExit.status, reason: overlapExit.reason })})`);
  });

