  test('route (c) PPID-failure exact carry control (codex gate round 15, Finding 2): a genuinely MATCHING coarse second read keeps the existing behavior', async () => {
    // The control: the second read DEGRADES too (both reads coarse, the
    // PPID changes) — the ppid-changed torn class carries the first read's
    // coarse identity (unchanged), the observe layer stays non-deciding
    // (the same-generation coarse identity against the exact bound), and
    // the lawful disappearance holds.
    const { observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const BOUND = 'kinfo:1:100000';
    const PS_TEXT = 'Thu Jan  1 00:00:01 1970';
    const nonce = 'a'.repeat(64);
    let psCallsF2c = 0;
    const verdict = await observeLocalProcess({
      pid: 4_194_303, nonce, expectedStartIdentity: BOUND,
      absenceConfirmation: async () => 'absent',
      osSeams: {
        platform: 'darwin',
        runProcess: async (launch) => {
          const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
          if (args.includes('eww')) return { code: 0, stdout: `node 4194303 ZCODE_SHELL_WAIT_CAPTURE_NONCE=${nonce}\n`, stderr: '' };
          psCallsF2c += 1;
          const ppid = psCallsF2c === 1 ? 4_194_302 : 999_999; // the PPID changes between the reads
          return { code: 0, stdout: ` 4194303  ${ppid}  ${PS_TEXT}\n`, stderr: '' };
        },
        kinfoExact: async () => {
          throw new Error('the exact bridge failed transiently'); // BOTH reads degrade
        },
      },
    });
    assert.deepEqual([verdict.status, verdict.reason], ['unestablished', 'liveness-read-failed'],
      `the ppid-changed torn class stays non-deciding (measured: ${JSON.stringify(verdict)})`);
    assert.equal(verdict.observedStartIdentity, PS_TEXT, 'the first read\u2019s coarse identity rides (unchanged)');
    const presence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 4_194_303, ppid: 4_194_302, startIdentity: BOUND, nonce, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
      queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: verdict.readStartedEpochMs - 100, identityReadEpochMs: verdict.readStartedEpochMs - 50, readEpochMs: verdict.readStartedEpochMs - 40, absenceConfirmed: null,
    };
    const absence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 4_194_303, nonce },
      readStartedEpochMs: verdict.readEpochMs + 100, identityReadEpochMs: verdict.readEpochMs + 150, readEpochMs: verdict.readEpochMs + 200, absenceConfirmed: true,
    };
    const exit = await adjudicateLocalExit({ presence, absenceReads: [verdict, absence] });
    assert.equal(exit.status, 'disappeared',
      `the lawful disappearance holds for the torn coarse pair (measured: ${JSON.stringify({ status: exit.status, reason: exit.reason })})`);
  });

