  test('route (c) termination capture-carry guard (codex gate round 18, Finding 1): the verification evidence is compared against the CAPTURE\u2019S carried exact identity — a later same-second exact B never signals', async () => {
    // The codex-review finding: when capture returns a mixed-resolution
    // identity, identity.startIdentity is coarse but
    // identity.observedStartIdentity preserves exact generation A. A later
    // exact generation B from the same second compares as same against that
    // coarse identity, and the guard ignored the capture's exact carry —
    // SIGTERM reached B despite the evidence proving replacement. The guard
    // compares the verification evidence against the capture's carried
    // exact identity before authorizing either signal.
    const { terminateVerifiedProcess } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const COARSE_CAPTURE = 'Thu Jan  1 00:00:01 1970'; // the capture's coarse startIdentity
    const CAPTURED_EXACT_A = 'kinfo:1:100000'; // the capture's carried exact generation
    const VERIFIED_EXACT_B = 'kinfo:1:200000'; // a later same-second exact generation
    let killCalls = 0;
    const outcome = await terminateVerifiedProcess(
      // The captured identity: coarse startIdentity + the carried exact A.
      { pid: 4_194_303, ppid: 4_194_302, nonce: 'a'.repeat(64), startIdentity: COARSE_CAPTURE, observedStartIdentity: CAPTURED_EXACT_A },
      {
        readIdentity: async () => ({
          pid: 4_194_303, ppid: 4_194_302,
          startIdentity: VERIFIED_EXACT_B, // exact B: same-second, compares same against the coarse capture
          nonce: 'a'.repeat(64),
        }),
        kill: (pid, signal) => { killCalls += 1; void pid; void signal; return true; },
        waitForExit: async () => {},
      },
    );
    assert.equal(outcome.attempted, false,
      `the verification evidence is compared against the capture\u2019s carried exact identity (measured: ${JSON.stringify(outcome)})`);
    assert.equal(killCalls, 0, 'neither signal reaches B');
    assert.equal(outcome.signalled, null);
    assert.ok(outcome.failure !== null && /identity changed/u.test(outcome.failure),
      `the honest identity-change classification (measured: ${JSON.stringify(outcome)})`);
    // The CONTROL (a): a positively-matching verification — the capture's
    // own exact generation A observed as the verification's startIdentity —
    // signals as before.
    let matchingKills = 0;
    const matching = await terminateVerifiedProcess(
      { pid: 4_194_303, ppid: 4_194_302, nonce: 'a'.repeat(64), startIdentity: COARSE_CAPTURE, observedStartIdentity: CAPTURED_EXACT_A },
      {
        readIdentity: async () => ({
          pid: 4_194_303, ppid: 4_194_302, startIdentity: CAPTURED_EXACT_A,
          nonce: 'a'.repeat(64),
        }),
        kill: () => { matchingKills += 1; return true; },
        waitForExit: async () => {},
      },
    );
    assert.equal(matching.attempted, true, 'a positively-matching carried identity signals');
    assert.equal(matchingKills, 1, 'the signal reaches the verified target');
    assert.equal(matching.exited, true);
    // The CONTROL (b): a REAL different-generation verification still blocks.
    const foreign = await terminateVerifiedProcess(
      { pid: 4_194_303, ppid: 4_194_302, nonce: 'a'.repeat(64), startIdentity: COARSE_CAPTURE, observedStartIdentity: CAPTURED_EXACT_A },
      {
        readIdentity: async () => ({
          pid: 4_194_303, ppid: 4_194_302, startIdentity: 'Thu Jan  1 00:00:02 1970', // a different second
          nonce: 'a'.repeat(64),
        }),
        kill: () => { throw new Error('the control must never signal a foreign generation'); },
        waitForExit: async () => {},
      },
    );
    assert.equal(foreign.attempted, false, 'a real different-generation verification still blocks');
    assert.ok(foreign.failure !== null && /identity changed/u.test(foreign.failure),
      `the identity-change classification (measured: ${JSON.stringify(foreign)})`);
  });

  test('route (c) termination learned-reference retention (codex gate round 20, Finding 1): a same-second successor observed mid-sequence is generation-changed — the escalation never signals it', async () => {
    // The codex-review finding: when capture returns only a coarse identity,
    // each termination read independently accepts any exact generation from
    // that second — cleanup could observe exact generation A, send it
    // SIGTERM, then observe the same-second successor B and send B SIGKILL
    // (the injected reproduction reports successful cleanup after signalling
    // BOTH generations). The termination sequence now RETAINS the exact
    // identities learned across its reads (including the exit polling) and
    // cross-checks every subsequent read against them: the generation change
    // fires at B's read and the escalation refuses by name.
    const { terminateVerifiedProcess } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const COARSE_CAPTURE = 'Thu Jan  1 00:00:01 1970'; // the capture's coarse startIdentity
    const EXACT_A = 'kinfo:1:100000'; // the generation the verification observes
    const EXACT_B = 'kinfo:1:200000'; // a same-second successor observed by the exit polling
    const signals = [];
    let reads = 0;
    // NO waitForExit injection: the DEFAULT exit polling runs — the polls
    // observe B through the real path the finding names.
    const outcome = await terminateVerifiedProcess(
      { pid: 4_194_303, ppid: 4_194_302, nonce: 'a'.repeat(64), startIdentity: COARSE_CAPTURE },
      {
        readIdentity: async () => {
          reads += 1;
          // reads 1-2: the gone-check + the pre-signal verification observe
          // exact A (SIGTERM's lawful target); reads 3+: the exit polling and
          // the pre-kill verification observe the same-second successor B.
          return {
            pid: 4_194_303, ppid: 4_194_302,
            startIdentity: reads <= 2 ? EXACT_A : EXACT_B,
            nonce: 'a'.repeat(64),
          };
        },
        kill: (pid, signal) => { void pid; signals.push(signal); return true; },
      },
    );
    assert.equal(outcome.attempted, true, `the SIGTERM reached the verified generation A (measured: ${JSON.stringify(outcome)})`);
    assert.deepEqual(signals, ['SIGTERM'],
      `the escalation never signals B (measured: ${JSON.stringify(signals)})`);
    assert.equal(outcome.signalled, 'SIGTERM');
    assert.equal(outcome.exited, false,
      `the replacement's survival is never the target's exit (measured: ${JSON.stringify(outcome)})`);
    assert.ok(outcome.failure !== null && /identity changed during termination/u.test(outcome.failure),
      `the generation-change fires at B's read (measured: ${JSON.stringify(outcome)})`);
  });

