  test('route (c) second-read-failure later-read carry (codex gate round 27, Finding 1): the inspector\u2019s SECOND-read ps-FAILURE identity-change refusal CARRIES the SECOND read\u2019s exact identity and its collection bounds — never the first read\u2019s', async () => {
    // The codex-review finding: when the FIRST exact read observes A and the
    // SECOND read observes the same-second successor B before its ps query
    // FAILS, the round-10 Finding-1 refusal rode rideObservedIdentity's
    // FIRST-read copy (A) — the termination tracker then compared that
    // carried A against its learned A, never latched the generation change,
    // and a degraded-to-matching-ps cleanup re-authorized signalling the
    // replacement B. The later observation is the replacement evidence: the
    // SECOND-read-failure refusal must carry the SECOND read's identity with
    // its own collection bounds (the same later-read carry rule the
    // non-failure mismatch path applies — codex gate round 25, Finding 1).
    // The CONTROL: a genuinely-MATCHING second read whose ps query fails
    // keeps the lawful query-failed class (its carried A is the SAME
    // generation — never positive replacement evidence, never the
    // identity-change refusal), and the non-failure mismatch path is the
    // round-25 Finding-1 row unchanged.
    const { inspectVerifiedProcessIdentity } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const NONCE = 'a'.repeat(64);
    const LIVE_PS = { code: 0, stdout: ' 4194303  4194302 Thu Jan  1 00:00:01 1970\n', stderr: '' };
    let kinfoCalls = 0;
    await assert.rejects(
      inspectVerifiedProcessIdentity(4_194_303, NONCE, 'FAKE_ZCODE_PROCESS_NONCE', {
        platform: 'darwin',
        environ: 'present',
        runProcess: async (launch) => {
          const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
          if (args.includes('eww')) return LIVE_PS; // never reached (the marker is seamed 'present')
          // The FIRST sub-read's ps query succeeds (live); the SECOND
          // sub-read's ps query FAILS after its kinfo observed B — the
          // observedThenQueryFailed shape.
          if (launch?.command === 'ps') {
            if (launch.args.includes('-p')) {
              if (kinfoCalls >= 2) throw new Error('the ps identity query failed transiently');
              return LIVE_PS;
            }
          }
          return LIVE_PS;
        },
        kinfoExact: async () => {
          kinfoCalls += 1;
          // The inspector's FIRST sub-read observes exact A; its SECOND
          // sub-read observes the same-second successor B before the ps
          // failure — the finding's schedule.
          if (kinfoCalls === 1) return { sec: 1, usec: 100000 };
          return { sec: 1, usec: 200000 };
        },
      }),
      (error) => {
        assert.match(String(error?.message ?? ''), /identity changed/u,
          `the second-read-failure mismatch refuses by name (measured: ${error?.message})`);
        assert.equal(error?.observedStartIdentity, 'kinfo:1:200000',
          `the refusal carries the SECOND (later) read's exact identity — the replacement evidence (measured: ${error?.observedStartIdentity})`);
        assert.ok(Number.isSafeInteger(error?.observedIdentityTakenEpochMs) && Number.isSafeInteger(error?.observedIdentityCompletedEpochMs),
          `the carried identity keeps its collection bounds as a unit (measured: ${JSON.stringify({ taken: error?.observedIdentityTakenEpochMs, completed: error?.observedIdentityCompletedEpochMs })})`);
        assert.equal(error?.observedThenQueryFailed, undefined,
          `the refusal is the identity-change class, not the raw query-failure ride (measured: ${error?.observedThenQueryFailed})`);
        assert.equal(kinfoCalls, 2, `the real double-read ran (measured: ${kinfoCalls})`);
        return true;
      },
    );
    // The CONTROL: a genuinely-MATCHING second read (A then A) whose ps
    // query fails keeps the lawful query-failed class — the carried A is the
    // SAME generation, never positive replacement evidence.
    let controlKinfoCalls = 0;
    await assert.rejects(
      inspectVerifiedProcessIdentity(4_194_303, NONCE, 'FAKE_ZCODE_PROCESS_NONCE', {
        platform: 'darwin',
        environ: 'present',
        runProcess: async (launch) => {
          const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
          if (args.includes('eww')) return LIVE_PS;
          if (launch?.command === 'ps' && Array.isArray(launch.args) && launch.args.includes('-p')) {
            if (controlKinfoCalls >= 2) throw new Error('the ps identity query failed transiently');
            return LIVE_PS;
          }
          return LIVE_PS;
        },
        kinfoExact: async () => {
          controlKinfoCalls += 1;
          return { sec: 1, usec: 100000 }; // EVERY sub-read: the same exact generation A
        },
      }),
      (error) => {
        assert.equal(error?.observedThenQueryFailed, true,
          `the matching second-read failure keeps the lawful query-failed class (measured: ${JSON.stringify({ message: error?.message, observedThenQueryFailed: error?.observedThenQueryFailed })})`);
        assert.equal(error?.observedStartIdentity, 'kinfo:1:100000',
          `the same-generation carry keeps the observed A (measured: ${error?.observedStartIdentity})`);
        assert.doesNotMatch(String(error?.message ?? ''), /identity changed/u,
          `the same-generation failure never reclassifies as the identity-change refusal (measured: ${error?.message})`);
        return true;
      },
    );
  });

