  test('route (c) cancellation recheck (§32.12 Finding 3): an abort during the exact read never starts the ps query — not on the exact path and not on the degradation path', async () => {
    // The codex-review finding: the inspector's cancellation checks surround
    // the COMBINED readStart operation, so they cannot prevent the ps query
    // that readMacProcessStart starts AFTER the exact read returns — an
    // observation aborted while the exact read is in flight still started a
    // new subprocess after the window closed, extending teardown by its
    // two-second timeout. The exact reader rechecks the observation's
    // cancellation between the exact query and the ps query, and on the
    // degradation path.
    const { observeLocalProcess } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const controller = new AbortController();
    let psQueries = 0;
    let kinfoQueries = 0;
    // The REAL darwin read path (no ps SEAM — a ps seam would route the
    // inspection through the seam-composition lambda, which queries ps
    // BEFORE the exact read and issues no subprocess): the ps identity read
    // runs through the runProcess seam, so the counter counts the actual
    // subprocess dispatch the finding names.
    const psIdentityRun = () => {
      psQueries += 1;
      return { code: 0, stdout: ' 4194303  4194302 Sun Nov  2 01:30:00 2025\n', stderr: '' };
    };
    const abortedVerdict = await observeLocalProcess({
      pid: 4_194_303, nonce: 'a'.repeat(64), abortSignal: controller.signal,
      osSeams: {
        platform: 'darwin',
        runProcess: psIdentityRun,
        kinfoExact: async () => {
          kinfoQueries += 1;
          controller.abort(); // the window closes while the exact read is in flight
          return { sec: 1793855520, usec: 123000 };
        },
        environ: 'present',
      },
    });
    assert.equal(psQueries, 0, `no ps subprocess may start after the window closed (measured: ${psQueries})`);
    assert.equal(kinfoQueries, 1, 'the in-flight exact read completed; the recheck happens between the two queries');
    assert.equal(abortedVerdict.status, 'unestablished', JSON.stringify(abortedVerdict));
    assert.equal(abortedVerdict.observedStartIdentity, 'kinfo:1793855520:123000',
      'the observed identity rides the window-closed failure (never a fabricated read)');
    // The DEGRADATION path: an exact read that fails while aborted also
    // never starts the ps query.
    const controller2 = new AbortController();
    let psQueries2 = 0;
    const degradedAborted = await observeLocalProcess({
      pid: 4_194_303, nonce: 'a'.repeat(64), abortSignal: controller2.signal,
      osSeams: {
        platform: 'darwin',
        runProcess: () => { psQueries2 += 1; return { code: 0, stdout: ' 4194303  4194302 Sun Nov  2 01:30:00 2025\n', stderr: '' }; },
        kinfoExact: async () => { controller2.abort(); return { malformed: 3240 }; },
        environ: 'present',
      },
    });
    assert.equal(psQueries2, 0, `the degradation path rechecks too (measured: ${psQueries2})`);
    assert.equal(degradedAborted.status, 'unestablished', JSON.stringify(degradedAborted));
    // The CONTROL: a non-aborted read issues BOTH queries on BOTH double
    // reads and settles — unchanged.
    let psQueries3 = 0;
    let kinfoQueries3 = 0;
    const live = await observeLocalProcess({
      pid: 4_194_303, nonce: 'a'.repeat(64),
      osSeams: {
        platform: 'darwin',
        // (codex gate round 5, Finding 2 fixture alignment) the ps text is
        // second 1793855520's own rendering — the row's non-aborted
        // both-queries control is unchanged; the previously misaligned text
        // described a different second and the read combination now
        // (correctly) refuses it.
        runProcess: () => { psQueries3 += 1; return { code: 0, stdout: ' 4194303  4194302 Thu Nov  5 05:12:00 2026\n', stderr: '' }; },
        kinfoExact: async () => { kinfoQueries3 += 1; return { sec: 1793855520, usec: 123000 }; },
        environ: 'present',
      },
    });
    assert.deepEqual([live.status, live.reason], ['established', null], JSON.stringify(live));
    assert.equal(kinfoQueries3, 2, 'the non-aborted double read queries the exact reader twice');
    assert.equal(psQueries3, 2, 'the non-aborted double read queries ps twice (unchanged)');
  });

  test('an environment-NONCE mismatch is a named non-reuse fact — the confirmed absence still adjudicates', async () => {
    // Round-25 finding: the nonce-mismatch throw ALSO carried 'identity
    // changed', so the regex labeled a nonce-verification failure as proven
    // PID reuse and adjudicateLocalExit permanently latched it — verified
    // presence A -> nonce mismatch -> verified same-generation presence ->
    // confirmed absence incorrectly stayed pid-start-identity-reused. A
    // nonce mismatch is now its OWN named non-reuse class; only an OBSERVED
    // OS start-identity change is generation-change evidence.
    const { inspectVerifiedProcessIdentity, observeLocalProcess, adjudicateLocalExit } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    // Round-27 refinement of this fixture: the mismatch read's observed
    // start identity now RIDES the verdict and the exit adjudicator compares
    // it with the BOUND generation — so the non-latching arm must be
    // SAME-generation (lstart 'S1', the bound identity). A mismatch read
    // that observed a DIFFERENT start identity is positive replacement
    // evidence and latches (the round-27 test covers that shape).
    const psReads = [
      { pid: 4_194_303, ppid: 4000, lstart: 'S1' },
      { pid: 4_194_303, ppid: 4000, lstart: 'S1' },
    ];
    let psCall = 0;
    const nonceMismatchInspect = () => inspectVerifiedProcessIdentity(4_194_303, 'b'.repeat(64), 'ZCODE_SHELL_WAIT_CAPTURE_NONCE', {
      platform: 'darwin',
      ps: async () => psReads[psCall++ % 2],
      environ: 'mismatch',
    });
    const nonceMismatch = await observeLocalProcess({
      pid: 4_194_303, nonce: 'b'.repeat(64), nowEpochMs: 2000,
      inspect: nonceMismatchInspect,
    });
    assert.equal(nonceMismatch.status, 'unestablished', 'the nonce-mismatch failure is named uncertainty');
    assert.equal(nonceMismatch.reason, 'liveness-read-failed', 'it maps to the non-reuse torn class — never the reuse class');
    assert.equal(nonceMismatch.observation, null);
    // The full sequence: presence A -> nonce mismatch -> same-generation
    // presence -> confirmed absence adjudicates the absence normally.
    const live = await observeLocalProcess({
      pid: 4_194_303, nonce: 'b'.repeat(64), nowEpochMs: 1000,
      inspect: async () => ({ pid: 4_194_303, ppid: 4000, startIdentity: 'S1', nonce: 'b'.repeat(64) }),
    });
    const liveAgain = await observeLocalProcess({
      pid: 4_194_303, nonce: 'b'.repeat(64), nowEpochMs: 2500,
      inspect: async () => ({ pid: 4_194_303, ppid: 4000, startIdentity: 'S1', nonce: 'b'.repeat(64) }),
    });
    const absence = await observeLocalProcess({ pid: 4_194_303, nonce: 'b'.repeat(64), nowEpochMs: 3000, inspect: async () => undefined });
    const exit = await adjudicateLocalExit({ presence: live, absenceReads: [nonceMismatch, liveAgain, absence] });
    assert.equal(exit.status, 'disappeared', 'the confirmed absence adjudicates normally — the nonce failure never latches');
    assert.equal(exit.reason, null);
    assert.equal(exit.firstVerifiedAbsenceEpochMs, 3000);
    // Class sweep: an OBSERVED start-identity change is still the reuse class.
    const psReadsChange = [
      { pid: 4_194_303, ppid: 4000, lstart: 'Thu Jan  1 00:00:00 2026' },
      { pid: 4_194_303, ppid: 4000, lstart: 'Fri Jan  2 00:00:00 2026' },
    ];
    let changeCall = 0;
    const identityChange = await observeLocalProcess({
      pid: 4_194_303, nonce: 'b'.repeat(64), nowEpochMs: 2000,
      inspect: () => inspectVerifiedProcessIdentity(4_194_303, 'b'.repeat(64), 'ZCODE_SHELL_WAIT_CAPTURE_NONCE', {
        platform: 'darwin',
        ps: async () => psReadsChange[changeCall++ % 2],
        environ: 'present',
      }),
    });
    assert.equal(identityChange.reason, 'start-identity-generation-changed', 'the observed start-identity change keeps the reuse class');
    const latched = await adjudicateLocalExit({ presence: live, absenceReads: [identityChange, absence] });
    assert.equal(latched.status, 'unestablished');
    assert.equal(latched.reason, 'pid-start-identity-reused', 'the observed start-identity change still latches');
  });

