  test('route (c) default-reader refusal carry (codex gate round 24, Finding 1): the SIGTERM exit polling\u2019s generation-change refusal CARRIES the successor — no SIGKILL, the latched outcome', async () => {
    // The codex-review finding: during SIGTERM exit polling, observing a
    // same-second successor throws the DEFAULT reader's plain error without
    // carrying its identity or permanently latching the mismatch.
    // terminateVerifiedProcess only consumes error-carried
    // observedStartIdentity, so its polling catch permits escalation; if the
    // next inspection degrades to matching coarse ps text, verification
    // passes and SIGKILL reaches the successor (exact A -> exact B -> coarse
    // -> gone produced both signals and exited: true, failure: null). The
    // reader's generation-change refusals now PRESERVE the successor identity
    // on the thrown error (design (a) — the round-23 Finding-1 consumption
    // path latches). NO readProcessIdentity and NO terminateProcessIdentity
    // injection: the DEFAULT reader and the DEFAULT termination run;
    // process.kill is intercepted solely to record the default termination's
    // signals (the synthetic pid never reaches a real process).
    const PSEUDO_PID = 4_194_303;
    const SIGNALS = [];
    const originalKill = process.kill;
    process.kill = (pid, signal) => {
      if (pid === PSEUDO_PID) { SIGNALS.push(signal); return true; }
      return originalKill.call(process, pid, signal);
    };
    let exitPollingStarted = false;
    let postSignalKinfoCalls = 0;
    let gonePhase = false;
    try {
      const runOutcome = await runHeldHostTurn({
        gatePath: 'unused-gate',
        launch: async () => ({ result: new Promise((resolve) => setTimeout(() => resolve({ code: 0, stdout: '', stderr: '' }), 60)), terminate: async () => {} }),
        waitForGate: async () => {},
        // The coarse capture (no exact carry): the tracked generation A is
        // learned by the reader's lifetime retention from the held-phase read.
        captureProcessIdentity: async () => ({ pid: PSEUDO_PID, ppid: 4_194_302, nonce: CAPTURE_NONCE, startIdentity: 'Thu Jan  1 00:00:01 1970', markerEpochMs: 4_200 }),
        waitForProcessExit: async (expected, phase, trackedRead) => {
          // The natural watcher rejects with its deadline (the round-22
          // failure shape that reaches the termination cleanup); the
          // termination phases drive the reviewer's schedule.
          if (phase === 'natural') throw new Error('the exact fake-ZCode process remained alive during natural');
          if (phase === 'terminate') {
            exitPollingStarted = true;
            await trackedRead(expected); // the reader's generation-change refusal throws here
            throw new Error('the verified process remained alive during terminate');
          }
          gonePhase = true;
          if (await trackedRead(expected) === undefined) return;
          throw new Error('the verified process remained alive during kill');
        },
        releaseGate: async () => {},
        localObservation: DECLARATION,
        localObservationObserverOptions: {
          osSeams: {
            platform: 'darwin',
            runProcess: async (launch) => {
              const args = Array.isArray(launch?.args) ? launch.args.join(' ') : '';
              if (args.includes('eww')) return { code: 0, stdout: `node 4194303 FAKE_ZCODE_PROCESS_NONCE=${CAPTURE_NONCE}\n`, stderr: '' };
              if (gonePhase) return { code: 1, stdout: '' }; // the process is gone
              return { code: 0, stdout: ' 4194303  4194302 Thu Jan  1 00:00:01 1970\n' }; // second 1: matches every generation's coarse second
            },
            kinfoExact: async () => {
              // Every pre-SIGTERM inspection: the tracked generation A.
              if (!exitPollingStarted) return { sec: 1, usec: 100000 };
              postSignalKinfoCalls += 1;
              // The SIGTERM exit polling's inspection: the same-second
              // successor B (both sub-reads agree — a clean exact B read;
              // the reader's lifetime retention refuses it).
              if (postSignalKinfoCalls <= 2) return { sec: 1, usec: 200000 };
              // The degraded pre-kill verification: the exact bridge fails
              // on both sub-reads — the read downgrades to the MATCHING ps
              // text (no exact carry; the reader passes it).
              throw new Error('the exact bridge failed transiently');
            },
          },
        },
        captureLocalObservationIdentity: async () => admissionEstablished(),
        observeLocalObservationIdentity: async () => osEstablished(),
        captureLocalBrokerObservationIdentity: async () => ({ ...admissionEstablished(), identity: { role: 'broker-daemon', nonce: CAPTURE_NONCE, entryRealpath: BROKER_ENTRY, configRealpathSha256: 'b'.repeat(64), pid: 60200, ppid: 60100, firstWriteEpochMs: 3_020, startOriginMs: 3_000.2, firstWritePreciseMs: 3_020.6 } }),
        observeLocalBrokerObservationIdentity: async () => osEstablished({ row: 'daemon' }),
        observeLocalTransportObservationIdentity: async () => osEstablished({ row: 'transport' }),
        sleep: async () => {},
        now: (() => { let value = 0; return () => (value += 500); })(),
        holdMs: 5_000,
        budgetMs: 60_000,
        processNonce: CAPTURE_NONCE,
      });
      assert.fail(`the natural-watcher rejection never resolves the turn (measured: ${JSON.stringify(runOutcome)})`);
    } catch (error) {
      if (String(error?.message ?? '').startsWith('the natural-watcher rejection never resolves')) throw error;
      const held = /** @type {any} */ (error)?.heldTurn;
      assert.deepEqual(SIGNALS, ['SIGTERM'],
        `the carried successor latches at the refusal — SIGKILL never fires (measured: ${JSON.stringify(SIGNALS)})`);
      assert.equal(held?.cleanup?.verifiedProcessTerminated, false,
        `the proven replacement is never a clean termination (measured: ${JSON.stringify(held?.cleanup?.verifiedProcessTerminated)})`);
      assert.ok(Array.isArray(held?.cleanup?.errors) && held.cleanup.errors.some((entry) => /identity changed during termination/u.test(String(entry instanceof Error ? entry.message : entry))),
        `the latched outcome rides the cleanup (measured: ${JSON.stringify((held?.cleanup?.errors ?? []).map((entry) => entry instanceof Error ? entry.message : entry))})`);
    } finally {
      process.kill = originalKill;
    }
  });

