  test('route (c) transport mixed-capture carry seeding (codex gate round 24, Finding 2): the capture\u2019s exact CARRY seeds the tracker \u2014 a phase-3 observation carrying the same-second successor latches against it', async () => {
    // The codex-review finding: when identity capture is mixed-resolution,
    // transportIdentity.startIdentity is coarse but
    // transportIdentity.observedStartIdentity retains exact generation A.
    // The seed ignored A, allowing a phase-3 observation carrying same-second
    // successor B to initialize the reference instead of latching
    // replacement; a subsequent confirmed absence was then accepted. The seed
    // now accepts the capture's exact CARRY in addition to its own
    // startIdentity (the runtime's learning order \u2014 the carried identity
    // first), and the phase-3 evidence is cross-checked against it.
    const held = await runHeldHostTurn({
      gatePath: 'unused-gate',
      launch: async () => ({ result: new Promise((resolve) => setTimeout(() => resolve({ code: 0, stdout: '', stderr: '' }), 400)), terminate: async () => {} }),
      waitForGate: async () => {},
      // The MIXED-resolution capture: coarse startIdentity + the exact carry A.
      captureProcessIdentity: async () => ({ pid: 60300, ppid: 60200, nonce: TRANSPORT_NONCE, startIdentity: 'Thu Jan  1 00:00:04 1970', observedStartIdentity: 'kinfo:4:100000', markerEpochMs: 4_200 }),
      readProcessIdentity: async () => ({ pid: 60300, ppid: 60200, nonce: TRANSPORT_NONCE, startIdentity: 'Thu Jan  1 00:00:04 1970' }),
      waitForProcessExit: async () => {},
      terminateProcessIdentity: async () => ({ attempted: true, signalled: 'SIGTERM', exited: true, failure: null }),
      releaseGate: async () => {},
      localObservation: DECLARATION,
      // The transport observation INJECTION (by CALL ORDER): call 1 is the
      // PHASE-3 transport observation \u2014 the second-4 coarse text matching the
      // mixed capture's second while CARRYING the same-second successor B;
      // calls 2+ are the EXIT RETRIES \u2014 the subsequent confirmed absence (the
      // reviewer's schedule).
      observeLocalTransportObservationIdentity: (() => {
        let transportSeamCalls = 0;
        return (input) => {
          void input;
          transportSeamCalls += 1;
          if (transportSeamCalls === 1) {
            return Promise.resolve({
              localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
              observation: { pid: 60300, ppid: 60200, startIdentity: 'Thu Jan  1 00:00:04 1970', startInstantEpochMs: 4000, ppidChangedFromCapture: null, nonce: TRANSPORT_NONCE },
              observedStartIdentity: 'kinfo:4:200000', // the carried same-second successor B
              queried: { pid: 60300, nonce: TRANSPORT_NONCE },
              readStartedEpochMs: 4150, identityReadEpochMs: 4170, readEpochMs: 4400, absenceConfirmed: null,
            });
          }
          return Promise.resolve({
            localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
            observation: null, queried: { pid: 60300, nonce: TRANSPORT_NONCE },
            readStartedEpochMs: 6000, identityReadEpochMs: 6050, readEpochMs: 6100, absenceConfirmed: true,
          });
        };
      })(),
      captureLocalObservationIdentity: async () => admissionEstablished(),
      observeLocalObservationIdentity: (() => {
        let invocationReads = 0;
        return async () => {
          invocationReads += 1;
          if (invocationReads === 1) return osEstablished();
          return {
            localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
            observation: null, queried: { pid: 60100, nonce: CAPTURE_NONCE },
            readStartedEpochMs: 5000, identityReadEpochMs: 5050, readEpochMs: 5100, absenceConfirmed: true,
          };
        };
      })(),
      captureLocalBrokerObservationIdentity: async () => ({ ...admissionEstablished(), identity: { role: 'broker-daemon', nonce: CAPTURE_NONCE, entryRealpath: BROKER_ENTRY, configRealpathSha256: 'b'.repeat(64), pid: 60200, ppid: 60100, firstWriteEpochMs: 3_020, startOriginMs: 3_000.2, firstWritePreciseMs: 3_020.6 } }),
      observeLocalBrokerObservationIdentity: async () => osEstablished({ row: 'daemon' }),
      sleep: (ms) => new Promise((resolve) => setTimeout(resolve, Math.min(ms, 5))),
      now: (() => { let value = 0; return () => (value += 500); })(),
      holdMs: 2_000,
      budgetMs: 10_000_000,
      processNonce: TRANSPORT_NONCE,
    });
    const transportBlock = held.cleanup.localObservation;
    assert.ok(transportBlock, 'the held record carries the local-observation block');
    assert.equal(transportBlock.transportExitGenerationLatched, true,
      `the capture's exact carry seeds the tracker \u2014 the carried successor latches (measured: ${transportBlock.transportExitGenerationLatched})`);
    assert.equal(transportBlock.transportExit.status, 'absent',
      'the subsequent absence persists as the exit fact, never credited through the latch');
    // The binding is PRESERVED for replay: the persisted marker carries the
    // capture's exact carry alongside the coarse captured identity.
    assert.equal(transportBlock.ancestryEndpoints?.transportMarker?.observedStartIdentity, 'kinfo:4:100000',
      `the capture's exact carry rides the persisted marker (measured: ${JSON.stringify(transportBlock.ancestryEndpoints?.transportMarker?.observedStartIdentity)})`);
  });

