  test('route (c) signal-throw absence post-read latch recheck (codex gate round 29, Finding 1): BOTH kill-throw catches collect the absence and then must recheck the terminal latch BEFORE crediting the exit', async () => {
    // The codex-review finding: the two signal-throw catch sites still did
    // `if (await trackTerminationRead(identity) === undefined) { outcome.exited
    // = true; return outcome; }`. The awaited read can be the default
    // reader's observed-then-gone conversion: kinfo observes the same-second
    // successor B, the tracker sets terminationGenerationChanged DURING the
    // await, and the catch credited the proven replacement's absence as the
    // target's clean exit (measured on the pre-fix bytes:
    // `{"attempted":true,"signalled":null,"exited":true,"failure":null}`). The
    // latch is now rechecked after the absence is collected and before the
    // exit is credited at BOTH sites; a hit walks the existing named
    // changed-during-termination refusal. NO readIdentity injection: the
    // DEFAULT reader and the REAL catch paths run; kill is intercepted to
    // throw the synthetic signal failure and record the signals.
    const { terminateVerifiedProcess } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const PSEUDO_PID = 4_194_303;
    const PSEUDO_PPID = 4_194_302;
    const EXACT_A = 'kinfo:1:100000';
    const PS_MATCHING = 'Thu Jan  1 00:00:01 1970';
    const PS_LIVE = ` ${PSEUDO_PID}  ${PSEUDO_PPID} ${PS_MATCHING}\n`;
    const PS_GONE = { code: 1, stdout: '', stderr: '' };
    /** @param {'SIGTERM' | 'SIGKILL'} signalToThrow */
    const runThrowingArm = async (signalToThrow) => {
      const liveCalls = signalToThrow === 'SIGTERM' ? 4 : 6;
      let kinfoCalls = 0;
      let psCalls = 0;
      const signals = [];
      const outcome = await terminateVerifiedProcess(
        { pid: PSEUDO_PID, ppid: PSEUDO_PPID, nonce: 'a'.repeat(64), startIdentity: EXACT_A },
        {
          inspectOsSeams: {
            platform: 'darwin',
            environ: 'present',
            runProcess: async () => {
              psCalls += 1;
              return psCalls <= liveCalls ? { code: 0, stdout: PS_LIVE, stderr: '' } : PS_GONE;
            },
            kinfoExact: async () => {
              kinfoCalls += 1;
              // Every read BEFORE the throwing catch observes the verified
              // generation A; the catch's tracked read observes the
              // same-second successor B and the following ps query finds the
              // pid gone — the observed-then-gone conversion latches DURING
              // the awaited absence read.
              return kinfoCalls <= liveCalls ? { sec: 1, usec: 100000 } : { sec: 1, usec: 200000 };
            },
          },
          kill: (pid, signal) => {
            void pid; signals.push(signal);
            if (signal === signalToThrow) throw new Error('the synthetic signal failed');
            return true;
          },
          waitForExit: async (_expected, phase) => {
            if (phase === 'kill') return;
            throw new Error('the exact verified process remained alive during terminate');
          },
        },
      );
      return { outcome, signals };
    };
    const term = await runThrowingArm('SIGTERM');
    assert.deepEqual(term.signals, ['SIGTERM'],
      `the SIGTERM throw leaves only the attempted signal recorded (measured: ${JSON.stringify(term.signals)})`);
    assert.equal(term.outcome.attempted, true, `the SIGTERM was attempted (measured: ${JSON.stringify(term.outcome)})`);
    assert.equal(term.outcome.signalled, null);
    assert.equal(term.outcome.exited, false,
      `the SIGTERM catch never credits the latched successor's absence as the target's exit (measured: ${JSON.stringify(term.outcome)})`);
    assert.ok(term.outcome.failure !== null && /identity changed during termination/u.test(term.outcome.failure),
      `the SIGTERM catch walks the named changed-during-termination refusal (measured: ${JSON.stringify(term.outcome)})`);
    const kill = await runThrowingArm('SIGKILL');
    assert.deepEqual(kill.signals, ['SIGTERM', 'SIGKILL'],
      `the SIGKILL throw leaves both attempted signals recorded (measured: ${JSON.stringify(kill.signals)})`);
    assert.equal(kill.outcome.attempted, true, `the escalation was attempted (measured: ${JSON.stringify(kill.outcome)})`);
    assert.equal(kill.outcome.signalled, 'SIGTERM');
    assert.equal(kill.outcome.exited, false,
      `the SIGKILL catch never credits the latched successor's absence as the target's exit (measured: ${JSON.stringify(kill.outcome)})`);
    assert.ok(kill.outcome.failure !== null && /identity changed during termination/u.test(kill.outcome.failure),
      `the SIGKILL catch walks the named changed-during-termination refusal (measured: ${JSON.stringify(kill.outcome)})`);
  });

