  test('integration-completion transport-retry exact generations replay (codex gate round 17, Finding 1 mirror): two persisted transport retries with different exact generations latch the reuse', () => {
    // The replay mirror of the round-17 Finding-1 runtime rule: the
    // persisted transport sequence RETAINS and CROSS-COMPARES the exact
    // generations its reads learned — two exact generations in the same
    // second with different usec are definitively different generations
    // (the reuse latch); matching exact generations keep the lawful path.
    const TRANSPORT_COARSE = 'Thu Jan  1 00:00:01 1970';
    const SCOPE = sha('f'.repeat(64));
    const transportRetry = (exact, readStarted, readEpoch) => ({
      class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 4,
      observation: { pid: 60300, ppid: 60200, startIdentity: exact, startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE },
      queried: { pid: 60300, nonceSha256: SCOPE },
      readStartedEpochMs: readStarted, identityReadEpochMs: readStarted + 50, readEpochMs: readEpoch, absenceConfirmed: null,
    });
    // The RED arm: the coarse transport echo + two exact retries (A then B).
    const replaced = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: 'kinfo:1:0', daemonIdentity: 'kinfo:2:500000',
      brokerObservationReadStarted: 2600, brokerObservationIdentityRead: 2660, brokerObservationRead: 2700,
      transportIdentity: TRANSPORT_COARSE,
      transportPresenceReads: [transportRetry('kinfo:1:100000', 3000, 3100), transportRetry('kinfo:1:200000', 4000, 4100)],
    }));
    assert.equal(replaced.localProcessDuties.settled, false, JSON.stringify(replaced.localProcessDuties.refusals));
    assert.ok(replaced.localProcessDuties.refusals.includes('transport-exit-generation-foreign'),
      `the replay cross-compares the transport retries' exact generations (actual ${JSON.stringify(replaced.localProcessDuties.refusals)})`);
    // The CONTROL arm: MATCHING exact generations keep the lawful path.
    const matching = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: 'kinfo:1:0', daemonIdentity: 'kinfo:2:500000',
      brokerObservationReadStarted: 2600, brokerObservationIdentityRead: 2660, brokerObservationRead: 2700,
      transportIdentity: TRANSPORT_COARSE,
      transportPresenceReads: [transportRetry('kinfo:1:100000', 3000, 3100), transportRetry('kinfo:1:100000', 4000, 4100)],
    }));
    assert.deepEqual(matching.localProcessDuties.refusals, [],
      `matching exact generations keep the lawful path (actual ${JSON.stringify(matching.localProcessDuties.refusals)})`);
    assert.equal(matching.localProcessDuties.settled, true);
  });

