  test('integration-completion baseline seeding replay (codex gate round 17, Finding 2 mirror): the presence\u2019s carried exact G1 seeds the reference — a later same-second exact successor G2 latches; WITHOUT the seed the lawful path holds', () => {
    // The replay mirror of the round-17 Finding-2 runtime rule: the
    // reference is SEEDED from the persisted baseline's admissible exact
    // carry — a later same-second exact successor G2 is compared against
    // the BASELINE's generation, never learned as the first. The control
    // arm: WITHOUT the seed (a coarse-only baseline) G2 is learned as the
    // first reference and the lawful path holds.
    const COARSE_BOUND = 'Thu Jan  1 00:00:01 1970';
    const SCOPE = sha('n'.repeat(64));
    const laterExactG2 = {
      class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 4,
      observation: { pid: 60100, ppid: 600, startIdentity: 'kinfo:1:200000', startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE },
      queried: { pid: 60100, nonceSha256: SCOPE },
      readStartedEpochMs: 1200, identityReadEpochMs: 1250, readEpochMs: 1300, absenceConfirmed: null,
    };
    const seeded = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: COARSE_BOUND, daemonIdentity: 'kinfo:2:500000',
      presenceObservedStartIdentity: 'kinfo:1:100000', // the baseline's carried exact G1: the seed
      presenceReadStarted: 1100, presenceIdentityRead: 1150, presenceRead: 1200,
      brokerObservationReadStarted: 3600, brokerObservationIdentityRead: 3660, brokerObservationRead: 3700,
      appendBlockReads: [laterExactG2],
    }));
    assert.equal(seeded.localProcessDuties.settled, false, JSON.stringify(seeded.localProcessDuties.refusals));
    assert.ok(seeded.localProcessDuties.refusals.includes('exit-reuse-latched'),
      `the seeded reference catches the later same-second successor (actual ${JSON.stringify(seeded.localProcessDuties.refusals)})`);
    // The control arm: WITHOUT the seed — the lawful path holds.
    const unseeded = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: COARSE_BOUND, daemonIdentity: 'kinfo:2:500000',
      presenceReadStarted: 1100, presenceIdentityRead: 1150, presenceRead: 1200,
      brokerObservationReadStarted: 3600, brokerObservationIdentityRead: 3660, brokerObservationRead: 3700,
      appendBlockReads: [laterExactG2],
    }));
    assert.deepEqual(unseeded.localProcessDuties.refusals, [],
      `without the seed the lawful path holds (actual ${JSON.stringify(unseeded.localProcessDuties.refusals)})`);
    assert.equal(unseeded.localProcessDuties.settled, true);
  });

