  test('integration-completion transport tracking seeding replay (codex gate round 18, Finding 3 mirror): the persisted transport observation\u2019s exact carry seeds the reference — the first exit retry\u2019s same-second successor latches', async () => {
    // The replay mirror of the round-18 Finding-3 runtime seeding rule: the
    // persisted transport observation's exact carry seeds the reference —
    // the first exit retry's same-second successor B latches against the
    // seeded A. The CONTROL arm: a coarse-only transport observation
    // (no exact carry) keeps the current behavior.
    const TRANSPORT_COARSE = 'Thu Jan  1 00:00:01 1970';
    const SCOPE = sha('f'.repeat(64));
    const transportRetry = (exact, readStarted, readEpoch, observedCarry) => ({
      class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 4,
      observation: { pid: 60300, ppid: 60200, startIdentity: exact, startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE },
      ...(observedCarry !== undefined ? { observedStartIdentity: observedCarry } : {}),
      queried: { pid: 60300, nonceSha256: SCOPE },
      readStartedEpochMs: readStarted, identityReadEpochMs: readStarted + 50, readEpochMs: readEpoch, absenceConfirmed: null,
    });
    const transportExitWithCarry = {
      class: 'os-live-observation', status: 'absent', reason: 'no-such-process', localProcessObservationVersion: 4,
      observation: null, queried: { pid: 60300, nonceSha256: SCOPE },
      observedStartIdentity: 'kinfo:1:300000', // the terminal exit's carried successor
      observedIdentityReadEpochMs: 8000, observedIdentityCompletedEpochMs: 8010,
      readStartedEpochMs: 8000, readEpochMs: 8100, absenceConfirmed: true,
    };
    // The RED arm: the transport observation carrying exact A (the seeded
    // reference); the first exit retry observes same-second B; the terminal
    // exit carries the successor.
    const seeded = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: 'kinfo:1:0', daemonIdentity: 'kinfo:2:500000',
      transportIdentity: TRANSPORT_COARSE,
      transportObservationObservedStartIdentity: 'kinfo:1:100000', // the phase-3's exact carry A: the seed
      transportPresenceReads: [transportRetry('kinfo:1:200000', 3000, 3100)],
      transportExitOverride: transportExitWithCarry,
    }));
    assert.equal(seeded.localProcessDuties.settled, false, JSON.stringify(seeded.localProcessDuties.refusals));
    assert.ok(seeded.localProcessDuties.refusals.includes('transport-exit-generation-foreign'),
      `the seeded reference catches the exit retry and the terminal exit\u2019s carry (actual ${JSON.stringify(seeded.localProcessDuties.refusals)})`);
    // The CONTROL arm: a coarse-only transport observation (no exact carry)
    // — the current behavior.
    const coarseOnly = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: 'kinfo:1:0', daemonIdentity: 'kinfo:2:500000',
      transportIdentity: TRANSPORT_COARSE,
      transportPresenceReads: [transportRetry('kinfo:1:200000', 3000, 3100)],
    }));
    assert.notEqual(coarseOnly.localProcessDuties.refusals.includes('transport-exit-generation-foreign'), true,
      `a coarse-only transport observation keeps the current behavior (actual ${JSON.stringify(coarseOnly.localProcessDuties.refusals)})`);
  });

