  test('integration-completion replay recency-ordered learning (codex gate round 16, Finding 3): a STALE pre-baseline exact observation never becomes the learned reference — the runtime outcome replays', async () => {
    // The codex-review finding: the replay reference was updated before
    // applying the read's recency rules — an exact observation collected
    // before the coarse presence baseline became the reference and caused a
    // later exact observation to trigger exit-reuse-latched, while the
    // runtime skips that stale observation (the recency filter) and returns
    // disappeared. The replay learns the reference only from evidence
    // admitted by the decision ordering + recency checks.
    const COARSE_BOUND = 'Thu Jan  1 00:00:01 1970';
    const SCOPE = sha('n'.repeat(64));
    // readX: exact A collected BEFORE the coarse presence baseline (its
    // identity instant 1050 < the baseline's 2000) — the stale observation
    // the runtime skips.
    const readX = {
      class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 4,
      observation: { pid: 60100, ppid: 600, startIdentity: 'kinfo:1:100000', startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE },
      queried: { pid: 60100, nonceSha256: SCOPE },
      readStartedEpochMs: 1000, identityReadEpochMs: 1050, readEpochMs: 1100, absenceConfirmed: null,
    };
    const readY = {
      class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 4,
      observation: { pid: 60100, ppid: 600, startIdentity: 'kinfo:1:200000', startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE },
      queried: { pid: 60100, nonceSha256: SCOPE },
      readStartedEpochMs: 3000, identityReadEpochMs: 3050, readEpochMs: 3100, absenceConfirmed: null,
    };
    const joined = nativeInterruptionGateDInput(record({
      companionStartEpochMs: 1000, daemonStartEpochMs: 2500,
      companionIdentity: COARSE_BOUND, daemonIdentity: 'kinfo:2:500000',
      presenceReadStarted: 1900, presenceIdentityRead: 2000, presenceRead: 2100,
      brokerObservationReadStarted: 3600, brokerObservationIdentityRead: 3660, brokerObservationRead: 3700,
      appendBlockReads: [readX, readY],
    }));
    assert.deepEqual(joined.localProcessDuties.refusals, [],
      `the stale pre-baseline observation never becomes the reference (actual ${JSON.stringify(joined.localProcessDuties.refusals)})`);
    assert.equal(joined.localProcessDuties.settled, true);
    // RUNTIME/REPLAY AGREEMENT: the runtime on the same sequence returns
    // disappeared (the stale observation skipped by the recency filter).
    const runtime = await import('../tools/shell-wait-probe/local-process-observation.mjs');
    const runtimeScope = 'a'.repeat(64); // the runtime verdicts carry the RAW nonce (hex-64)
    const runtimePresence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 60100, ppid: 600, startIdentity: COARSE_BOUND, nonce: runtimeScope, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
      queried: { pid: 60100, nonce: runtimeScope },
      readStartedEpochMs: 1900, identityReadEpochMs: 2000, readEpochMs: 2100, absenceConfirmed: null,
    };
    const runtimeReadX = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 60100, ppid: 600, startIdentity: 'kinfo:1:100000', nonce: runtimeScope, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
      queried: { pid: 60100, nonce: runtimeScope },
      readStartedEpochMs: 1000, identityReadEpochMs: 1050, readEpochMs: 1100, absenceConfirmed: null,
    };
    const runtimeReadY = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
      observation: { pid: 60100, ppid: 600, startIdentity: 'kinfo:1:200000', nonce: runtimeScope, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
      queried: { pid: 60100, nonce: runtimeScope },
      readStartedEpochMs: 3000, identityReadEpochMs: 3050, readEpochMs: 3100, absenceConfirmed: null,
    };
    const runtimeAbsence = {
      localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
      observation: null, queried: { pid: 60100, nonce: runtimeScope },
      readStartedEpochMs: 5000, identityReadEpochMs: 5050, readEpochMs: 5100, absenceConfirmed: true,
    };
    const runtimeExit = await runtime.adjudicateLocalExit({ presence: runtimePresence, absenceReads: [runtimeReadX, runtimeReadY, runtimeAbsence] });
    assert.equal(runtimeExit.status, 'disappeared',
      `the runtime skips the stale observation (measured: ${JSON.stringify({ status: runtimeExit.status, reason: runtimeExit.reason })})`);
  });

