      reads: transitionCarry === null ? [replayAbsence] : [replayTransition(transitionCarry), replayAbsence],
      exit: { localProcessObservationVersion: 1, class: 'exit-absence', status: 'disappeared', reason: null, boundIdentity: { pid: 60100, startIdentity: BOUND, nonceSha256: sha(scopeNonce) }, lastVerifiedPresenceEpochMs: 2100, firstVerifiedAbsenceEpochMs: 5100, exitCorroboratedByMeta: false },
