describe('codex gate round 39 review-mwcrgo5m-8t4hr1 (two P2): error-carried identities compare against the captured generation, and exact observation bounds classify before the replacement latch', async () => {
  const { adjudicateLocalExit, terminateVerifiedProcess } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
  const PID = 4_194_303;
  const PPID = 4_194_302;
  const NONCE = 'a'.repeat(64);
  const TEXT_1 = 'Thu Jan  1 00:00:01 1970';

  const runTermination = async (capture, pollingKinfo) => {
    let kinfoCalls = 0;
    let psCalls = 0;
    const signals = [];
    return await terminateVerifiedProcess(
      { pid: PID, ppid: PPID, nonce: NONCE, startIdentity: capture },
      {
        inspectOsSeams: {
          platform: 'darwin',
          environ: 'present',
          runProcess: async () => {
            psCalls += 1;
            // The first two inspections read the matching coarse ps text;
            // the exit-polling read's ps query THROWS (the ps-failure carry).
            if (psCalls >= 5) throw new Error('ps exploded');
            return { code: 0, stdout: ` ${PID}  ${PPID} ${TEXT_1}\n`, stderr: '' };
          },
          kinfoExact: async () => {
            kinfoCalls += 1;
            if (kinfoCalls <= 4) return { malformed: 648 }; // the exact bridge is unavailable through the pre-signal reads
            if (kinfoCalls === 5) return pollingKinfo; // the polling read observes the exact generation before ps throws
            return null; // the post-signal reads observe the gone pid
          },
        },
        kill: (signalPid, signal) => { void signalPid; signals.push(signal); return true; },
      },
    ).then((outcome) => ({ outcome, signals }), (error) => ({ thrown: error }));
  };

  test('F1 (P2) → a failed inspection\'s exact carry is compared against the capture before seeding the reference (codex gate round 39, Finding 1)', async () => {
    // The codex-review finding: with a coarse capture and no learned exact
    // reference, a FAILED inspection can expose a definitively different
    // generation without latching replacement — the reviewer's schedule (a
    // second-1 capture; after SIGTERM kinfo returns `kinfo:2:100000`, the
    // following ps query throws, and the next read finds absence) let the
    // error-carry learning branch seed the successor, so termination
    // returned `exited: true, failure: null`. The carried evidence is now
    // compared against the captured identity and its exact carry
    // (representation-aware: a different second is definitively different)
    // BEFORE initializing the learned reference — a definitive difference
    // latches; same-generation or unresolvable carries keep the lawful
    // seeding.
    const refused = await runTermination(TEXT_1, { sec: 2, usec: 100000 });
    assert.deepEqual([refused.outcome?.attempted, refused.outcome?.signalled, refused.outcome?.exited, refused.outcome?.failure],
      [true, 'SIGTERM', false, 'the exact fake-ZCode process identity changed during termination'],
      `the different-second ps-throw carry is the latched replacement, never a clean exit (measured: ${JSON.stringify(refused)})`);
  });

  test('F1 (P2) controls → same-generation carries keep the lawful seeding and the matching exact capture is unchanged (codex gate round 39, Finding 1)', async () => {
    // (a) the carry in the coarse capture's OWN second proves no difference —
    // the lawful seeding stands and the gone pid is the clean exit; (b) a
    // MATCHING exact capture (its reference seeded from the capture) keeps
    // the lawful exit.
    const sameSecond = await runTermination(TEXT_1, { sec: 1, usec: 500000 });
    assert.deepEqual([sameSecond.outcome?.exited, sameSecond.outcome?.failure], [true, null],
      `the same-generation carry keeps the lawful seeding (measured: ${JSON.stringify(sameSecond.outcome)})`);
    const exactCapture = await runTermination('kinfo:1:100000', { sec: 1, usec: 100000 });
    assert.deepEqual([exactCapture.outcome?.exited, exactCapture.outcome?.failure], [true, null],
      `the matching exact capture keeps the lawful exit (measured: ${JSON.stringify(exactCapture.outcome)})`);
  });

  const BASE = 'kinfo:1:500000';
  const PRED = 'kinfo:1:100000';
  const exactPresence = {
    localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
    observation: { pid: PID, ppid: PPID, startIdentity: BASE, nonce: NONCE, startInstantEpochMs: 150, ppidChangedFromCapture: null },
    queried: { pid: PID, nonce: NONCE },
    readStartedEpochMs: 1550, identityReadEpochMs: 1600, readEpochMs: 1650, absenceConfirmed: null,
  };
  const predecessorRead = (taken, completed) => ({
    localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
    observation: { pid: PID, ppid: PPID, startIdentity: PRED, nonce: NONCE, startInstantEpochMs: 150, ppidChangedFromCapture: null },
    observedStartIdentity: PRED, observedIdentityReadEpochMs: taken, observedIdentityCompletedEpochMs: completed,
    queried: { pid: PID, nonce: NONCE },
    readStartedEpochMs: 1210, identityReadEpochMs: 1700, readEpochMs: 1700, absenceConfirmed: null,
  });
  const exactAbsence = {
    localProcessObservationVersion: 4, class: 'os-live-observation', status: 'absent', reason: 'no-such-process',
    observation: null, queried: { pid: PID, nonce: NONCE },
    readStartedEpochMs: 1750, identityReadEpochMs: 1775, readEpochMs: 1800, absenceConfirmed: true,
  };

  test('F2 (P2) → exact observation bounds classify before the raw-relation replacement latch (codex gate round 39, Finding 2)', async () => {
    // The codex-review finding: a successful exact inspection can finish its
    // kernel reads before the presence baseline but complete its final ps
    // query afterward — the observer returns the EARLIER exact identity with
    // its kernel bounds and a LATER identityReadEpochMs. The reviewer's
    // schedule (the predecessor `kinfo:1:100000` collected during
    // [1220,1250], the baseline `kinfo:1:500000` collected during
    // [1550,1600], the delayed ps completion at 1700) reported
    // `pid-start-identity-reused` despite the predecessor being definitively
    // stale. The interval classification (the COLLECTION bounds — the kernel
    // window) now runs before this mismatch latches: definitively stale
    // evidence is old-era and never enters the latch branch.
    const stale = await adjudicateLocalExit({ presence: exactPresence, absenceReads: [predecessorRead(1220, 1250), exactAbsence] });
    assert.deepEqual([stale.status, stale.reason], ['disappeared', null],
      `the definitively stale predecessor never latches the reuse (measured: ${JSON.stringify({ status: stale.status, reason: stale.reason })})`);
    const without = await adjudicateLocalExit({ presence: exactPresence, absenceReads: [exactAbsence] });
    assert.deepEqual([without.status, without.reason], ['disappeared', null],
      `the predecessor-free schedule keeps its lawful disappearance (measured: ${JSON.stringify({ status: without.status, reason: without.reason })})`);
  });

  test('F2 (P2) controls → non-stale successor windows keep the latch/ambiguous classification (codex gate round 39, Finding 2)', async () => {
    // (a) a successor whose kernel window STARTS after the baseline
    // ([1620,1700] against [1550,1600]) still latches the reuse; (b) a
    // successor whose kernel window merely OVERLAPS the baseline
    // ([1500,1700]) takes the named ambiguous fact — the classification's
    // own semantics, never a raw latch.
    const post = await adjudicateLocalExit({ presence: exactPresence, absenceReads: [predecessorRead(1620, 1700), exactAbsence] });
    assert.deepEqual([post.status, post.reason], ['unestablished', 'pid-start-identity-reused'],
      `the post-baseline successor still latches (measured: ${JSON.stringify({ status: post.status, reason: post.reason })})`);
    const overlap = await adjudicateLocalExit({ presence: exactPresence, absenceReads: [predecessorRead(1500, 1700), exactAbsence] });
    assert.deepEqual([overlap.status, overlap.reason], ['unestablished', 'pid-start-identity-ambiguous'],
      `the overlapping successor is the named ambiguous fact (measured: ${JSON.stringify({ status: overlap.status, reason: overlap.reason })})`);
  });
});

