    staleA.observedIdentityCompletedEpochMs = 5100;
    const currentB = replayObservation(60100, 600, 'kinfo:1:500000', sha(scopeNonce), 7040, 7200, 7250);
    currentB.observedIdentityReadEpochMs = 7050;
    currentB.observedIdentityCompletedEpochMs = 7100;
