    assert.deepEqual([runtimeExit.status, runtimeExit.reason], ['disappeared', null],
      `the runtime excludes the stale own identity (measured: ${JSON.stringify({ status: runtimeExit.status, reason: runtimeExit.reason })})`);
    const replay = nativeInterruptionGateDInput(buildStaleOwnRecord()).localProcessDuties;
    assert.equal(replay.settled, true,
      `the replay credits the same runtime evidence — the stale own identity never seeds the retention (measured: ${JSON.stringify(replay.refusals)})`);
