    brokerObservation: { class: 'os-live-observation', status: 'established', reason: null, localProcessObservationVersion: 1, observation: { pid: 60200, ppid: 60100, startIdentity: 'S-DAEMON', startInstantEpochMs: 1000, ppidChangedFromCapture: null, nonceSha256: SCOPE }, queried: { pid: 60200, nonceSha256: SCOPE }, readStartedEpochMs: 1150, identityReadEpochMs: 1160, readEpochMs: 1300, absenceConfirmed: null },
