describe('codex gate round 50 review-mwe9xpn0-7mhztk (one P2): the exact marker binding refuses overlapping quantized timestamps', async () => {
  const { joinAncestryHops } = await import('../tools/shell-wait-probe/local-process-observation.mjs');
  const NONCE = 'a'.repeat(64);
  const DAEMON_WRITER = 'kinfo:1:0'; // ms-aligned creation 1000.0
  const CHILD_FRACTIONAL = 'kinfo:1:400'; // creation 1000.4 — usec 400 quantizes DOWN, persisted 1000
  const CHILD_ALIGNED = 'kinfo:1:0'; // ms-aligned creation 1000.0 — the persisted instant IS the creation
  const exactEndpoint = (pid, ppid, startIdentity, read) => ({
    localProcessObservationVersion: 4, class: 'os-live-observation', status: 'established', reason: null,
    observation: { pid, ppid, startIdentity, nonce: NONCE, startInstantEpochMs: 1000, ppidChangedFromCapture: null },
    queried: { pid, nonce: NONCE },
    readStartedEpochMs: read - 1000, identityReadEpochMs: read, readEpochMs: read, absenceConfirmed: null,
  });
  const witness = (childIdentity, childMs, firstWriteEpochMs = 1000) => ({
    localProcessObservationVersion: 4, class: 'spawn-ancestry-witness', status: 'established', reason: null,
    identity: {
      version: 3, startIdentityExact: true, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE,
      writerPid: 5200, writerStartIdentity: DAEMON_WRITER,
      childPid: 5300, childPpid: 5200, childStartIdentity: childIdentity, childNonce: NONCE,
      boundaryEpochMs: 1000, firstWriteEpochMs,
      startOriginMs: null, firstWritePreciseMs: null, childOsStartInstantMs: childMs,
    },
    readStartedEpochMs: 1000, readEpochMs: firstWriteEpochMs,
  });
  const run = (childIdentity, childMs, markerEpochMs, markerStartIdentity = childIdentity, firstWriteEpochMs = 1000) => joinAncestryHops({
    nonce: NONCE,
    companionObservation: null,
    daemonObservation: exactEndpoint(5200, 5100, DAEMON_WRITER, 2500),
    transportMarker: { pid: 5300, ppid: 5200, nonce: NONCE, startIdentity: markerStartIdentity },
    expectedTransportNonce: NONCE,
    markerEpochMs,
    daemonSpawnWitness: witness(childIdentity, childMs, firstWriteEpochMs),
  });
  const hop = (verdict) => verdict.hops[1];

  test('F1 (P2) → the exact marker binding refuses the marker tied with a downward-quantized child creation (codex gate round 50, Finding 1)', () => {
    // The codex-review finding: a child `kinfo:1:400` (creation 1000.4)
    // persists the ROUNDED start instant 1000, and a predecessor marker
    // written at 1000.2 also quantizes to 1000 — the exact mode disables the
    // ambiguity band, so the rounded tie credited the stale marker with
    // `witnessClass: 'spawn-boundary-capture'`. The marker's persisted time
    // is quantized to whole milliseconds by its own shape (markerEpochMs —
    // no fractional member exists to preserve), so the overlapping-tie
    // refusal is the honest terminal state: when the child's exact identity
    // is NOT millisecond-aligned AND quantizes DOWNWARD, a marker tied with
    // the persisted instant overlaps the true creation window — the
    // ambiguity is refused, never resolved as true (the module's convention;
    // the coarse band already refuses the same overlap as ambiguous).
    const stale = run(CHILD_FRACTIONAL, 1000, 1000);
    assert.deepEqual([hop(stale).status, hop(stale).reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'],
      `the marker tied with a downward-quantized child creation refuses as ambiguous (measured: ${JSON.stringify(hop(stale))})`);
    // The LAWFUL control: the marker a whole millisecond AFTER the persisted
    // instant (1100 — its true write ∈ [1100,1101) is strictly after the
    // 1000.4 creation) keeps the credit.
    // (codex gate round 58 review-mwfb8x00-exyttv, Finding 1 — the implicated
    // row disclosed: this control's witness write originally stayed at the
    // rounded 1000 while the witnessed child was created at 1000.4, a
    // chronology the now-independent exact child-creation check rightly
    // refuses. The witness write moves to the rounded 1100 so this row
    // exercises ONLY the marker binding it owns; the stale arm above still
    // refuses at the marker binding before any write ordering is consulted.)
    const lawful = run(CHILD_FRACTIONAL, 1000, 1100, CHILD_FRACTIONAL, 1100);
    assert.deepEqual([hop(lawful).status, hop(lawful).reason], ['established', null],
      `the marker after the quantized creation keeps the credit (measured: ${JSON.stringify(hop(lawful))})`);
    assert.equal(hop(lawful).witnessClass, 'spawn-boundary-capture');
  });

  test('F1 (P2) controls → the aligned tie now refuses the marker window check and the coarse band stays byte-identical (codex gate round 50, Finding 1; updated by round 63, Finding 1)', () => {
    // (a) the ALIGNED tie: a child `kinfo:1:0` (creation exactly 1000.0 —
    // the persisted instant IS the true creation) tied with marker 1000.
    // (codex gate round 63 review-mwfxlzpe-0fve20, Finding 1) the ALIGNED
    // exemption is RETIRED: the persisted marker time is rounded even for
    // an aligned child, so the true write window [999.5, 1000.5) contains
    // writes before the 1000.0 creation — the tie refuses the named
    // ambiguity (never resolved as true). The half-exact window-edge arm
    // below is the establishing tie; (b) the coarse record keeps the
    // registered ambiguity band byte-identically (a marker inside the
    // child's first possible second refuses the coarse ambiguous label).
    const aligned = run(CHILD_ALIGNED, 1000, 1000);
    assert.deepEqual([hop(aligned).status, hop(aligned).reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'],
      `the aligned tie refuses under the true marker window (measured: ${JSON.stringify(hop(aligned))})`);
    assert.equal(hop(aligned).witnessClass, undefined);
    const coarseWitness = {
      localProcessObservationVersion: 3, class: 'spawn-ancestry-witness', status: 'established', reason: null,
      identity: {
        version: 3, startIdentityExact: false, class: 'spawn-ancestry-witness', role: 'broker-daemon', nonce: NONCE,
        writerPid: 5200, writerStartIdentity: 'S-DAEMON',
        childPid: 5300, childPpid: 5200, childStartIdentity: 'S-TRANSPORT', childNonce: NONCE,
        boundaryEpochMs: 1500, firstWriteEpochMs: 2000,
        startOriginMs: null, firstWritePreciseMs: null, childOsStartInstantMs: 1000,
      },
      readStartedEpochMs: 1500, readEpochMs: 2000,
    };
    const coarseRun = joinAncestryHops({
      nonce: NONCE,
      companionObservation: null,
      daemonObservation: { ...exactEndpoint(5200, 5100, 'S-DAEMON', 2500), observation: { pid: 5200, ppid: 5100, startIdentity: 'S-DAEMON', nonce: NONCE, startInstantEpochMs: 1000, ppidChangedFromCapture: null } },
      transportMarker: { pid: 5300, ppid: 5200, nonce: NONCE },
      expectedTransportNonce: NONCE,
      markerEpochMs: 1100,
      daemonSpawnWitness: coarseWitness,
    });
    assert.deepEqual([hop(coarseRun).status, hop(coarseRun).reason], ['unestablished', 'spawn-witness-marker-generation-ambiguous'],
      `the coarse ambiguity band stays byte-identical (measured: ${JSON.stringify(hop(coarseRun))})`);
    assert.equal(hop(coarseRun).witnessClass, undefined);
  });
});

