    transportExit: { class: 'os-live-observation', status: 'absent', reason: 'no-such-process', localProcessObservationVersion: 1, observation: null, queried: { pid: 60300, nonceSha256: TRANSPORT }, readStartedEpochMs: 5300, identityReadEpochMs: 5350, readEpochMs: 5400, absenceConfirmed: true },
