describe('codex gate round 59 review-mwfewow5-9m2azr (one P1): the PPID-only rejection retains its first exact generation observation', async () => {
  const { runHeldHostTurn } = await import('../tools/shell-wait-probe/driver.mjs');
  const CAPTURE_NONCE = 'c'.repeat(64);
  const ENTRY = '/private/tmp/fixture-installed/skills/rescue/launcher.mjs';
  const BROKER_ENTRY = '/private/tmp/fixture-installed/scripts/zcode-broker.mjs';
  const DECLARATION = Object.freeze({
    captureDirectory: '/private/tmp/fixture-capture',
    nonce: CAPTURE_NONCE,
    entryRealpath: ENTRY,
    brokerEntryRealpath: BROKER_ENTRY,
  });
  const COARSE = 'Thu Jan  1 00:00:01 1970';
  const PID = 4_194_303;
  const PPID = 4_194_302;
  const admissionEstablished = () => ({
    localProcessObservationVersion: 1,
    class: 'startup-identity',
    status: 'established',
    reason: null,
    identity: {
      role: 'invocation', nonce: CAPTURE_NONCE, entryRealpath: ENTRY,
      argv: ['invoke-prepared', 'rescue'], pid: 60100, ppid: 600,
      firstWriteEpochMs: 1000, startOriginMs: 1000.1, firstWritePreciseMs: 1100.5,
    },
    readStartedEpochMs: 1000,
    readEpochMs: 1100,
  });
  const osEstablished = (over = {}) => {
    const row = over?.row ?? 'companion';
    const defaults = {
      companion: { pid: 60100, ppid: 600, startIdentity: 'S-COMPANION', nonce: CAPTURE_NONCE, startInstantEpochMs: 1_000 },
      daemon: { pid: 60200, ppid: 60100, startIdentity: 'S-DAEMON', nonce: CAPTURE_NONCE, startInstantEpochMs: 3_000 },
      transport: { pid: 60300, ppid: 60200, startIdentity: 'S-TRANSPORT', nonce: CAPTURE_NONCE, startInstantEpochMs: 5_000 },
    }[row];
    return {
      localProcessObservationVersion: 1,
      class: 'os-live-observation',
      status: 'established',
      reason: null,
      observation: { ...defaults, ppidChangedFromCapture: null, ...(over?.observation ?? {}) },
      queried: { pid: defaults.pid, nonce: defaults.nonce, ...(over?.queried ?? {}) },
      readStartedEpochMs: over?.readStartedEpochMs ?? (row === 'companion' ? 4_000 : row === 'daemon' ? 4_100 : 6_100),
      identityReadEpochMs: over?.identityReadEpochMs ?? (row === 'companion' ? 4_200 : row === 'daemon' ? 4_300 : 6_300),
      readEpochMs: over?.readEpochMs ?? (row === 'companion' ? 4_500 : row === 'daemon' ? 4_500 : 6_500),
      absenceConfirmed: null,
    };
  };
  const baseInput = (osSeams, captureIdentity) => ({
    gatePath: 'unused-gate',
    launch: async () => ({ result: new Promise((resolve) => setTimeout(() => resolve({ code: 0, stdout: '', stderr: '' }), 60)), terminate: async () => {} }),
    waitForGate: async () => {},
    captureProcessIdentity: async () => captureIdentity,
    terminateProcessIdentity: async () => ({ attempted: true, signalled: 'SIGTERM', exited: true, failure: null }),
    waitForProcessExit: async () => {},
    releaseGate: async () => {},
    localObservation: DECLARATION,
    localObservationObserverOptions: { osSeams },
    captureLocalObservationIdentity: async () => admissionEstablished(),
    observeLocalObservationIdentity: async () => osEstablished(),
    captureLocalBrokerObservationIdentity: async () => ({ ...admissionEstablished(), identity: { role: 'broker-daemon', nonce: CAPTURE_NONCE, entryRealpath: BROKER_ENTRY, configRealpathSha256: 'b'.repeat(64), pid: 60200, ppid: 60100, firstWriteEpochMs: 3_020, startOriginMs: 3_000.2, firstWritePreciseMs: 3_020.6 } }),
    observeLocalBrokerObservationIdentity: async () => osEstablished({ row: 'daemon' }),
    observeLocalTransportObservationIdentity: async () => osEstablished({ row: 'transport' }),
    sleep: async () => {},
    now: (() => { let value = 0; return () => (value += 500); })(),
    holdMs: 5_000,
    budgetMs: 60_000,
    processNonce: CAPTURE_NONCE,
  });
  /** The default termination (never the injected outcome) so the cleanup's
   * own verification/latch path is what the row measures; the ps call count
   * separates the held read (calls 1-2) from the cleanup reads (3-8) and the
   * post-signal absence (9+). The synthetic-PID signal spy (round 60,
   * Finding 1) records and swallows every default `process.kill`, so the
   * fixture can never signal a real process that happens to occupy the
   * synthetic pid; each row asserts the intended coverage. */
  const runHeldTurn = async (captureIdentity, seams) => withSyntheticSignalSpy([PID], () => runHeldHostTurn({
    ...baseInput({ platform: 'darwin', environ: 'present', ...seams }, captureIdentity),
    terminateProcessIdentity: undefined,
  }).catch((error) => error?.heldTurn ?? null));
  const psSequence = (heldRead, cleanupRead) => {
    let psCalls = 0;
    return async () => {
      psCalls += 1;
      if (psCalls <= 2) return heldRead;
      if (psCalls <= 8) return cleanupRead;
      return undefined;
    };
  };
  const cleanupErrors = (held) => (held?.cleanup?.errors ?? []).map((entry) => String(entry instanceof Error ? entry.message : entry));

  test('F1 (P1) → the PPID-only rejection retains the first exact generation, so a same-second cleanup successor is never signalled (codex gate round 59 review-mwfewow5-9m2azr)', async () => {
    // The codex-review finding: with a COARSE capture and no learned
    // reference, a PPID-mismatched inspection can observe exact generation A
    // without setting `heldTurnGenerationChanged` (the capture carries no
    // exact form to compare against). The retention condition required the
    // latch, so A was discarded; the cleanup then read a different
    // same-second exact B, learned it as the initial reference, verified it
    // against the matching coarse capture and signalled it — the reviewer
    // measured a SIGTERM attempt and `verifiedProcessTerminated: true` with
    // no cleanup errors. RED (measured on 14e11f4c in a clean `git clone
    // --shared` copy): verified true, errors []. The first exact observation
    // is now retained on this PPID-only rejection path exactly as on every
    // refusal path reached with no learned reference and an exact observed
    // identity: the cleanup's B is compared against A, the named
    // identity-changed refusal fires before any signal, and the termination
    // is never verified. The signal spy proves the refusal precedes the
    // signal gate (no synthetic-PID kill is attempted).
    let kinfoCalls = 0;
    const { result: held, signals } = await runHeldTurn(
      { pid: PID, ppid: PPID, nonce: CAPTURE_NONCE, startIdentity: COARSE, markerEpochMs: 4_200 },
      {
        ps: psSequence({ pid: PID, ppid: PPID + 1, lstart: COARSE }, { pid: PID, ppid: PPID, lstart: COARSE }),
        kinfoExact: async () => {
          kinfoCalls += 1;
          return kinfoCalls <= 2 ? { sec: 1, usec: 100000 } : { sec: 1, usec: 500000 };
        },
      },
    );
    assert.ok(held, 'premise: the failed turn carried its held record');
    assert.deepEqual(signals, [],
      `the refused successor is never signalled (measured: ${JSON.stringify(signals)})`);
    assert.equal(held.cleanup.verifiedProcessTerminated, false,
      `the same-second successor is never a verified termination (measured: ${JSON.stringify({ verified: held.cleanup.verifiedProcessTerminated, errors: cleanupErrors(held) })})`);
    assert.ok(cleanupErrors(held).some((message) => /identity changed/u.test(message)),
      `the cleanup carries the named identity-changed refusal (measured: ${JSON.stringify(cleanupErrors(held))})`);
    assert.equal(cleanupErrors(held).length, 1,
      `the refusal is the cleanup's only error — no signal/failure error rides beside it (measured: ${JSON.stringify(cleanupErrors(held))})`);
  });

  test('F1 (P1) controls → the same-generation exact, degraded-coarse and no-exact schedules keep their lawful terminations byte-identically (codex gate round 59 review-mwfewow5-9m2azr)', async () => {
    // (a) the SAME exact generation A on both the held and cleanup reads
    // (a reparented original) still terminates lawfully: the newly retained
    // reference equals the cleanup observation, so no latch fires; (b) the
    // retained exact A does not block a cleanup read degraded to the
    // matching COARSE text (the representation-aware same-generation
    // relation); (c) a held read with NO exact form retains nothing and
    // keeps the existing PPID-rejection/cleanup schedule byte-identically.
    // Every lawful arm signals exactly once through the synthetic-PID spy
    // (SIGTERM recorded and swallowed, never delegated to the OS).
    const sameExactRun = await runHeldTurn(
      { pid: PID, ppid: PPID, nonce: CAPTURE_NONCE, startIdentity: COARSE, markerEpochMs: 4_200 },
      {
        ps: psSequence({ pid: PID, ppid: PPID + 1, lstart: COARSE }, { pid: PID, ppid: PPID, lstart: COARSE }),
        kinfoExact: async () => ({ sec: 1, usec: 100000 }),
      },
    );
    const sameExact = sameExactRun.result;
    assert.equal(sameExact?.cleanup?.verifiedProcessTerminated, true,
      `the same-generation reparented original stays lawfully terminable (measured: ${JSON.stringify({ verified: sameExact?.cleanup?.verifiedProcessTerminated, errors: cleanupErrors(sameExact) })})`);
    assert.equal(cleanupErrors(sameExact).length, 0, 'no latch and no cleanup error on the same-generation exact arm');
    assert.deepEqual(sameExactRun.signals, [[PID, 'SIGTERM']],
      `the lawful same-generation termination signals exactly once (measured: ${JSON.stringify(sameExactRun.signals)})`);
    let degradedCalls = 0;
    const degradedCleanupRun = await runHeldTurn(
      { pid: PID, ppid: PPID, nonce: CAPTURE_NONCE, startIdentity: COARSE, markerEpochMs: 4_200 },
      {
        ps: psSequence({ pid: PID, ppid: PPID + 1, lstart: COARSE }, { pid: PID, ppid: PPID, lstart: COARSE }),
        kinfoExact: async () => {
          degradedCalls += 1;
          return degradedCalls <= 2 ? { sec: 1, usec: 100000 } : { malformed: 0 };
        },
      },
    );
    const degradedCleanup = degradedCleanupRun.result;
    assert.equal(degradedCleanup?.cleanup?.verifiedProcessTerminated, true,
      `the retained exact A matches the degraded cleanup text and stays terminable (measured: ${JSON.stringify({ verified: degradedCleanup?.cleanup?.verifiedProcessTerminated, errors: cleanupErrors(degradedCleanup) })})`);
    assert.equal(cleanupErrors(degradedCleanup).length, 0, 'the degraded same-generation cleanup carries no error');
    assert.deepEqual(degradedCleanupRun.signals, [[PID, 'SIGTERM']],
      `the lawful degraded cleanup signals exactly once (measured: ${JSON.stringify(degradedCleanupRun.signals)})`);
    const noExactRun = await runHeldTurn(
      { pid: PID, ppid: PPID, nonce: CAPTURE_NONCE, startIdentity: COARSE, markerEpochMs: 4_200 },
      {
        ps: psSequence({ pid: PID, ppid: PPID + 1, lstart: COARSE }, { pid: PID, ppid: PPID, lstart: COARSE }),
        kinfoExact: async () => ({ malformed: 0 }),
      },
    );
    const noExact = noExactRun.result;
    assert.equal(noExact?.cleanup?.verifiedProcessTerminated, true,
      `a no-exact held read retains nothing and keeps its lawful termination (measured: ${JSON.stringify({ verified: noExact?.cleanup?.verifiedProcessTerminated, errors: cleanupErrors(noExact) })})`);
    assert.equal(cleanupErrors(noExact).length, 0, 'the no-exact arm never latches');
    assert.deepEqual(noExactRun.signals, [[PID, 'SIGTERM']],
      `the lawful no-exact termination signals exactly once (measured: ${JSON.stringify(noExactRun.signals)})`);
  });
});

