    const replayExplicitOld = replayVerdict([rawExactAFailedOldEvidence, rawExactBFailedExplicitOld, rawAbsence], claimedDisappeared());
    assert.equal(replayExplicitOld.settled, true,
      `the explicit 6090 identity evidence keeps the replay settlement (measured: ${JSON.stringify({ settled: replayExplicitOld.settled, refusals: replayExplicitOld.refusals })})`);
    assert.deepEqual(replayExplicitOld.refusals, [], 'the two-phase bypass never fires at strictly-old identity evidence');
    // (boundary arm 2) identityReadEpochMs EXACTLY on the 6100 horizon is
    // the runtime's `>=` pre-filter arm — the tie still latches both sides,
    // so the new premise never weakens the at/after-horizon latch.
    const runtimeTie = runtimeVerdict([rawExactAFailedOldEvidence, rawExactBFailedTie, rawAbsence]);
    assert.equal(runtimeTie.status, 'unestablished',
      `the horizon-tie identity evidence keeps the runtime reuse refusal (measured: ${JSON.stringify({ status: runtimeTie.status, reason: runtimeTie.reason })})`);
    assert.equal(runtimeTie.reason, 'pid-start-identity-reused');
    const replayTie = replayVerdict([rawExactAFailedOldEvidence, rawExactBFailedTie, rawAbsence], claimedDisappeared());
    assert.equal(replayTie.settled, false,
      `the horizon-tie identity evidence keeps the replay reuse refusal (measured: ${JSON.stringify({ settled: replayTie.settled, refusals: replayTie.refusals })})`);
    assert.deepEqual(replayTie.refusals, ['exit-reuse-latched'], 'the at/after-horizon pre-filter arm keeps its exact refusal');
    // (reviewer's original schedule control) A returned 6160 and B returned
    // 6230 — B's identity evidence is at/after the 6100 horizon, the
    // runtime's early pre-filter latches, and the replay still latches.
    const runtimeOriginal = runtimeVerdict([rawExactAFailedOrdinary, rawExactBFailedOrdinary, rawAbsence]);
    assert.equal(runtimeOriginal.status, 'unestablished',
      `the original round-61 schedule keeps its runtime reuse refusal (measured: ${JSON.stringify({ status: runtimeOriginal.status, reason: runtimeOriginal.reason })})`);
